#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SceneProgram {
    pub scene_id: String,
    pub max_new_segments: usize,
    pub max_candidate_attempts: usize,
    pub segment_lengths_m: Vec<u32>,
    pub priority_purposes: Vec<String>,
    pub reach_distance_m: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub hierarchy: Option<RoadHierarchy>,
    /// Explicit demand-led supply policy. Required exactly by version 3.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub supply: Option<SupplyPolicy>,
}
/// Bounded limits for the version-3 real-parcel-supply road selection.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SupplyPolicy {
    pub version: u32,
    pub max_candidate_states: usize,
    pub preflight_budget_ms: u64,
    /// How version 3 obtains its roads. `append` runs the authored v1/v2
    /// automatic stage first and then appends demand-led roads to that trusted
    /// baseline; `replace` keeps the earlier "v3 instead of v2" semantics.
    pub mode: String,
}
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct RoadTier {
    pub id: String,
    pub role: String,
    pub width_m: u32,
    pub purposes: Vec<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct RoadHierarchy {
    pub tiers: Vec<RoadTier>,
}
impl RoadHierarchy {
    fn validate(&self) -> Result<(), TerrainError> {
        if !(2..=3).contains(&self.tiers.len()) {
            return Err(err("road hierarchy requires 2..=3 tiers"));
        }
        let mut ids = BTreeSet::new();
        let mut roles = BTreeSet::new();
        for tier in &self.tiers {
            if tier.id.is_empty()
                || !ids.insert(&tier.id)
                || !roles.insert(&tier.role)
                || !matches!(tier.role.as_str(), "collector" | "local" | "farm_access")
                || !matches!(tier.width_m, 8 | 12 | 16)
                || tier.purposes.is_empty()
                || tier
                    .purposes
                    .iter()
                    .any(|p| !matches!(p.as_str(), "urban" | "rural"))
                || tier.purposes.iter().collect::<BTreeSet<_>>().len() != tier.purposes.len()
            {
                return Err(err("invalid road hierarchy tier"));
            }
        }
        if !roles.iter().any(|role| role.as_str() == "collector")
            || !roles.iter().any(|role| role.as_str() == "local")
        {
            return Err(err("road hierarchy requires collector and local tiers"));
        }
        Ok(())
    }
    fn tier_for(&self, purpose: &str, collector: bool) -> Option<&RoadTier> {
        let roles: &[&str] = if collector {
            &["collector", "local", "farm_access"]
        } else if purpose == "urban" {
            &["local", "collector", "farm_access"]
        } else {
            &["farm_access", "local", "collector"]
        };
        roles
            .iter()
            .find_map(|role| {
                self.tiers.iter().find(|tier| {
                    tier.role == *role && tier.purposes.iter().any(|p| p == purpose)
                })
            })
    }
}
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Program {
    pub version: u32,
    pub scenes: Vec<SceneProgram>,
    /// Opt-in authorization for road-first planning in a scene that declares a
    /// STRUCTURED water body (`style.water` with a level policy).
    ///
    /// Only one value is accepted, [`STRUCTURED_WATER_OPT_IN`]
    /// (`"bridge-or-causeway"`), because the value is the engineering decision
    /// itself: the author states that every road segment over the water is
    /// carried by a registered bridge or causeway instead of by fill. Absent or
    /// any other value keeps the historical rule - a structured water body
    /// disables road-first entirely - so no existing input changes meaning.
    ///
    /// The string is validated in [`from_style`] and refused by name; it is not
    /// silently reinterpreted as a boolean.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub allow_structured_water: Option<String>,
}
