fn err(s: impl Into<String>) -> TerrainError {
    TerrainError(s.into())
}
/// Frozen ceilings for the version-3 demand-led supply strategy. Candidate
/// *states*, accepted roads and per-request frontage attempts are counted
/// separately so no loop can silently multiply the search.
const SUPPLY_MAX_CANDIDATE_STATES: usize = 128;
const SUPPLY_MAX_PREFLIGHT_MS: u64 = 180_000;
/// `pub(super)` so the B01-G1 harness measures with exactly the live evidence
/// cap instead of duplicating the number.
pub(super) const SUPPLY_SAMPLE_CAP: usize = 6;
/// How many real-supply candidates one accepted road may choose between. The
/// whole sweep still shares the single 128-state budget: batches only decide
/// *when* the sweep pauses for verification, never how far it may go.
const SUPPLY_BATCH: usize = 32;
pub fn from_style(style: &serde_json::Value) -> Result<Option<Program>, TerrainError> {
    let Some(value) = style.get("automaticRoadExtensions") else {
        return Ok(None);
    };
    let p: Program = serde_json::from_value(value.clone()).map_err(|e| err(e.to_string()))?;
    if !matches!(p.version, 1 | 2 | 3) || p.scenes.is_empty() {
        return Err(err("invalid automatic road program"));
    }
    if let Some(opt_in) = p.allow_structured_water.as_deref() {
        if opt_in != super::road_network::STRUCTURED_WATER_OPT_IN {
            return Err(err(format!(
                "allowStructuredWater must be \"{}\" when stated, not {opt_in:?}",
                super::road_network::STRUCTURED_WATER_OPT_IN
            )));
        }
    }
    let mut ids = BTreeSet::new();
    for s in &p.scenes {
        if !ids.insert(&s.scene_id)
            || s.scene_id.is_empty()
            || !(1..=256).contains(&s.max_new_segments)
            || !(1..=65536).contains(&s.max_candidate_attempts)
            || s.segment_lengths_m.is_empty()
            || s.segment_lengths_m.len() > 8
            || s.segment_lengths_m
                .iter()
                .any(|v| *v < 16 || *v > 1024 || v % 2 != 0)
            || s.segment_lengths_m.iter().collect::<BTreeSet<_>>().len()
                != s.segment_lengths_m.len()
            || s.priority_purposes.is_empty()
            || s.priority_purposes
                .iter()
                .any(|s| !matches!(s.as_str(), "urban" | "rural"))
            || s.priority_purposes.iter().collect::<BTreeSet<_>>().len()
                != s.priority_purposes.len()
            || !(8..=160).contains(&s.reach_distance_m)
            || (p.version >= 2 && s.hierarchy.is_none())
            || (p.version == 1 && s.hierarchy.is_some())
        {
            return Err(err("invalid automatic road scene limits/purposes"));
        }
        match (p.version, &s.supply) {
            (3, Some(policy))
                if policy.version == 1
                    && (1..=SUPPLY_MAX_CANDIDATE_STATES).contains(&policy.max_candidate_states)
                    && (1..=SUPPLY_MAX_PREFLIGHT_MS).contains(&policy.preflight_budget_ms) => {}
            (3, _) => return Err(err("supply policy must state version 1 and bounded limits")),
            (_, Some(_)) => return Err(err("supply policy requires automatic roads version 3")),
            _ => {}
        }
        if let Some(policy) = &s.supply {
            if policy.mode != "append" && policy.mode != "replace" {
                return Err(err("supply policy mode must be append or replace"));
            }
        }
        if let Some(hierarchy) = &s.hierarchy {
            hierarchy.validate()?;
        }
    }
    if p.version == 3 {
        // Demand-led selection needs stated demand: no synthesised second
        // source, and every request must be reachable through the authorized
        // hierarchy for its own purpose.
        let Some(frontage) = style.get("frontageProgram") else {
            return Err(err("version 3 supply selection requires a frontage program"));
        };
        let requests = frontage
            .get("requests")
            .and_then(|v| v.as_array())
            .ok_or_else(|| err("version 3 requires stated frontage requests"))?;
        if requests.is_empty() {
            return Err(err("version 3 requires stated frontage requests"));
        }
        for program in &p.scenes {
            let hierarchy = program
                .hierarchy
                .as_ref()
                .ok_or_else(|| err("version 3 requires a stated hierarchy"))?;
            let scoped: Vec<&serde_json::Value> = requests
                .iter()
                .filter(|r| r.get("sceneId").and_then(|v| v.as_str()) == Some(&program.scene_id))
                .collect();
            if scoped.is_empty() {
                return Err(err("version 3 scene has no frontage request"));
            }
            for request in scoped {
                let purpose = request
                    .get("purpose")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| err("version 3 request needs a purpose"))?;
                if !program.priority_purposes.iter().any(|p| p == purpose) {
                    return Err(err("version 3 request purpose is not a priority purpose"));
                }
                if hierarchy.tier_for(purpose, false).is_none() {
                    return Err(err("version 3 request purpose has no authorized road tier"));
                }
            }
        }
    }
    Ok(Some(p))
}
pub fn validate_manifest(m: &WorldManifest) -> Result<(), TerrainError> {
    if let Some(p) = from_style(&m.style)? {
        if super::height_encoding_from_style(&m.style).map_err(|e| err(e.to_string()))?
            != crate::height_payload::HeightEncoding::Millimetre
        {
            return Err(err("automatic roads require millimetre heights"));
        }
        for program in p.scenes {
            let scene = m
                .scenes
                .iter()
                .find(|s| s.scene_id == program.scene_id)
                .ok_or_else(|| err("automatic roads refer to unknown scene"))?;
            let w =
                super::water_geometry(super::water_kind(&m.style), &m.landmarks, scene, &m.style);
            if !super::road_network::enabled(&m.style, w) {
                return Err(err("automatic roads require active road-first planning"));
            }
        }
    }
    Ok(())
}
fn road_bounds(e: &EntityInstance, margin: i64) -> [i64; 4] {
    let (w, d) = if e.rotation_y_deg == 0. {
        (
            e.width_m as i64 / 2 + margin,
            e.depth_m as i64 / 2 + margin,
        )
    } else {
        (
            e.depth_m as i64 / 2 + margin,
            e.width_m as i64 / 2 + margin,
        )
    };
    [
        i64::from(e.world_x) - w,
        i64::from(e.world_z) - d,
        i64::from(e.world_x) + w,
        i64::from(e.world_z) + d,
    ]
}
fn distance(p: [i32; 2], r: [i64; 4]) -> u64 {
    let x = i64::from(p[0]);
    let z = i64::from(p[1]);
    (r[0] - x).max(x - r[2]).max(0) as u64 + (r[1] - z).max(z - r[3]).max(0) as u64
}
fn intersects(a: [i64; 4], b: [i64; 4]) -> bool {
    a[0] < b[2] && a[2] > b[0] && a[1] < b[3] && a[3] > b[1]
}
fn has_road(bounds: [i64; 4], roads: &[EntityInstance]) -> bool {
    roads.iter().any(|e| intersects(bounds, road_bounds(e, 0)))
}
fn nearest(p: [i32; 2], roads: &[EntityInstance]) -> Option<u64> {
    roads.iter().map(|e| distance(p, road_bounds(e, 0))).min()
}
/// Fixed junction levels of the network, derived from the road entities'
/// support. `pub(super)` only so the bounded B01-G1 feasibility harness in the
/// sibling supply module can read the same fixed node heights the live search
/// uses; the solver, thresholds and defaults are unchanged.
pub(super) fn levels(
    plan: &RoadNetworkPlan,
    roads: &[EntityInstance],
) -> Result<BTreeMap<[i32; 2], i32>, TerrainError> {
    let by_id: BTreeMap<_, _> = roads.iter().map(|e| (e.entity_id.as_str(), e)).collect();
    let mut result = BTreeMap::new();
    for n in &plan.nodes {
        let mut height = None;
        for e in plan.edges.iter().filter(|e| e.from == n.id || e.to == n.id) {
            let road = by_id
                .get(e.id.as_str())
                .ok_or_else(|| err("automatic growth parent road missing"))?;
            let h = road
                .grounding
                .road_profile
                .as_ref()
                .and_then(|p| p.height_at(f64::from(n.world_x), f64::from(n.world_z)))
                .unwrap_or(f64::from(road.ground_height_m()));
            let mm = (h * 1000.).round() as i32;
            if height.is_some_and(|old| old != mm) {
                return Err(err("automatic growth parent node has incompatible heights"));
            }
            height = Some(mm);
        }
        if let Some(h) = height {
            result.insert([n.world_x, n.world_z], h);
        }
    }
    Ok(result)
}
#[derive(Clone)]
struct Candidate {
    start: [i32; 2],
    end: [i32; 2],
    node: usize,
    priority: usize,
    served: usize,
    gain: u64,
    length: u32,
    tier_rank: u8,
    tier_role: Option<String>,
    road_width_m: u32,
}
impl Candidate {
    fn key(&self) -> [i32; 4] {
        [self.start[0], self.start[1], self.end[0], self.end[1]]
    }
    fn bounds(&self, margin: i64) -> [i64; 4] {
        let (mx, mz) = if self.start[1] == self.end[1] {
            (
                margin,
                self.road_width_m as i64 / 2 + 3 + margin,
            )
        } else {
            (
                self.road_width_m as i64 / 2 + 3 + margin,
                margin,
            )
        };
        [
            i64::from(self.start[0].min(self.end[0])) - mx,
            i64::from(self.start[1].min(self.end[1])) - mz,
            i64::from(self.start[0].max(self.end[0])) + mx,
            i64::from(self.start[1].max(self.end[1])) + mz,
        ]
    }
}
fn clear(
    c: &Candidate,
    plan: &RoadNetworkPlan,
    roads: &[EntityInstance],
    ctx: &AlignmentContext<'_>,
) -> Result<(), TerrainError> {
    let x = ((i64::from(c.start[0]) + i64::from(c.end[0])) / 2) as i32;
    let z = ((i64::from(c.start[1]) + i64::from(c.end[1])) / 2) as i32;
    let (hw, hd) = if c.start[1] == c.end[1] {
        (
            c.length as i32 / 2 + 4,
            c.road_width_m as i32 / 2 + 3,
        )
    } else {
        (
            c.road_width_m as i32 / 2 + 3,
            c.length as i32 / 2 + 4,
        )
    };
    if ctx
        .mask
        .check("auto-candidate".into(), "road", x, z, hw, hd)
        .is_some()
    {
        return Err(err("reserved_or_outside_zoning"));
    }
    let b = [
        i64::from(x - hw),
        i64::from(z - hd),
        i64::from(x + hw),
        i64::from(z + hd),
    ];
    for road in roads {
        // Same padded support rule, widened to the declared road tier.
        let (w, d) = if road.rotation_y_deg == 0. {
            (
                road.width_m as i64 / 2 + 4,
                road.depth_m as i64 / 2 + 3,
            )
        } else {
            (
                road.depth_m as i64 / 2 + 3,
                road.width_m as i64 / 2 + 4,
            )
        };
        let r = [
            i64::from(road.world_x) - w,
            i64::from(road.world_z) - d,
            i64::from(road.world_x) + w,
            i64::from(road.world_z) + d,
        ];
        let q = [
            b[0].max(r[0]),
            b[1].max(r[1]),
            b[2].min(r[2]),
            b[3].min(r[3]),
        ];
        if q[0] <= q[2]
            && q[1] <= q[3]
            && !road_extensions::shared_junctions(plan, &road.entity_id, c.start, c.end)
                .iter()
                .any(|p| {
                    let radius = i64::from(c.road_width_m / 2 + 3).max(8);
                    q[0] >= i64::from(p[0]) - radius
                        && q[2] <= i64::from(p[0]) + radius
                        && q[1] >= i64::from(p[1]) - radius
                        && q[3] <= i64::from(p[1]) + radius
                })
        {
            return Err(err("existing_road_crossing"));
        }
    }
    for site in &plan.roadside_sites {
        let (w, d) = site.world_half_extents();
        if b[0] < i64::from(site.world_x) + i64::from(w) + 4
            && b[2] > i64::from(site.world_x) - i64::from(w) - 4
            && b[1] < i64::from(site.world_z) + i64::from(d) + 4
            && b[3] > i64::from(site.world_z) - i64::from(d) - 4
        {
            return Err(err("existing_obligated_site"));
        }
    }
    Ok(())
}
fn category(reason: &str) -> String {
    if reason.contains("infeasible") || reason.contains("no feasible constant") {
        "profile_infeasible".into()
    } else if reason.contains("protected") || reason.contains("zoning") {
        "reserved_or_outside_zoning".into()
    } else if reason.contains("padded footprint") {
        "padded_support_fill".into()
    } else {
        reason.into()
    }
}
pub(super) fn append(
    plan: &mut RoadNetworkPlan,
    scene: &SceneSpec,
    t: &BakedTerrain,
    water: WaterGeometry,
    zones: &[LandUseZone],
    style: &serde_json::Value,
) -> Result<(), TerrainError> {
    append_declared(
        plan,
        scene,
        t,
        water,
        zones,
        style,
        NaturalSource::Undeclared,
    )
}

/// The automatic-road stage with an explicit declaration of the scene's
/// authoritative natural source. Version 3 (demand-led supply) refuses an
/// undeclared source outright: its candidate realization rebuilds the final
/// surface, and guessing a zero seed or silently falling back to a raster would
/// make the measured supply depend on an undeclared choice.
pub(super) fn append_declared(
    plan: &mut RoadNetworkPlan,
    scene: &SceneSpec,
    t: &BakedTerrain,
    water: WaterGeometry,
    zones: &[LandUseZone],
    style: &serde_json::Value,
    source: NaturalSource,
) -> Result<(), TerrainError> {
    let Some(all) = from_style(style)? else {
        return Ok(());
    };
    // The bounded-cut allowance of this world's longitudinal road profile, read
    // once: ␀ is a world that never opted in and keeps the fill-only solver.
    let profile_cut_mm = super::bounded_cut::CutPolicy::from_style(style).0.cap_mm();
    let version = all.version;
    let Some(program) = all
        .scenes
        .into_iter()
        .find(|s| s.scene_id == scene.scene_id)
    else {
        return Ok(());
    };
    if version == 3 {
        if source == NaturalSource::Undeclared {
            return Err(err(
                "version 3 supply requires a declared natural source (authored seed or supplied raster)",
            ));
        }
        let policy = program
            .supply
            .as_ref()
            .ok_or_else(|| err("version 3 requires a supply policy"))?;
        let mode = if policy.mode == "append" {
            SupplyMode::Append
        } else {
            SupplyMode::Replace
        };
        if mode == SupplyMode::Append {
            // The authored v1/v2 automatic stage runs first and becomes the
            // trusted baseline this demand-led phase appends to.
            append_legacy(plan, scene, t, water, zones, &program, profile_cut_mm)?;
        }
        let clock = WallClock::start();
        return append_supply_aware(
            plan,
            scene,
            t,
            water,
            zones,
            style,
            &program,
            mode,
            &clock,
            source,
        );
    }
    append_legacy(plan, scene, t, water, zones, &program, profile_cut_mm)
}

/// The authored v1/v2 automatic road stage. Version 3 `append` mode runs this
/// first so the frozen baseline keeps its identity, elevation and provenance.
fn append_legacy(
    plan: &mut RoadNetworkPlan,
    scene: &SceneSpec,
    t: &BakedTerrain,
    water: WaterGeometry,
    zones: &[LandUseZone],
    program: &SceneProgram,
    // The bounded-cut allowance of the longitudinal profile; ␀ keeps the
    // historical fill-only solver and the historical bytes.
    profile_cut_mm: i32,
) -> Result<(), TerrainError> {
    let original = plan.entities();
    let program = program.clone();
    let mut targets: Vec<_> = zones
        .iter()
        .filter(|z| program.priority_purposes.contains(&z.kind))
        .map(|z| {
            let centre = [
                z.world_x + (z.width_m / 2) as i32,
                z.world_z + (z.depth_m / 2) as i32,
            ];
            let before = nearest(centre, &original);
            let bounds = [
                i64::from(z.world_x),
                i64::from(z.world_z),
                i64::from(z.world_x) + i64::from(z.width_m),
                i64::from(z.world_z) + i64::from(z.depth_m),
            ];
            let entered = has_road(bounds, &original);
            Target {
                zone_bounds: bounds,
                before_has_road: entered,
                after_has_road: entered,
                zone_id: z.id.clone(),
                purpose: z.kind.clone(),
                centre,
                before_distance_m: before,
                after_distance_m: before,
            }
        })
        .collect();
    targets.sort_by(|a, b| a.zone_id.cmp(&b.zone_id));
    let ctx = AlignmentContext::new(scene, t, water, zones)?.with_cut(profile_cut_mm);
    let mut report = Report {
        version: 1,
        model: "bounded-purpose-centre-and-zone-growth-v2".into(),
        scope: "zone-road-intersection-and-centre-proximity-not-realized-land-or-global-optimality"
            .into(),
        program: program.clone(),
        stop_reason: String::new(),
        attempted_candidates: 0,
        accepted_segments: 0,
        generated_road_ids: vec![],
        targets,
        unserved_targets: 0,
        rejected_by_reason: BTreeMap::new(),
        rejection_examples: vec![],
        supply: vec![],
        sweep: vec![],
        sweep_exhausted: false,
        base_road_program: None,
        incomplete: false,
        incomplete_reason: None,
    };
    let mut attempted = BTreeSet::new();
    'growth: loop {
        let roads = plan.entities();
        let node_levels = levels(plan, &roads)?;
        for target in &mut report.targets {
            target.after_distance_m = nearest(target.centre, &roads);
            target.after_has_road = has_road(target.zone_bounds, &roads);
        }
        report.unserved_targets = report
            .targets
            .iter()
            .filter(|t| {
                !t.after_has_road
                    || t.after_distance_m
                        .is_none_or(|d| d > u64::from(program.reach_distance_m))
            })
            .count();
        let stop = if report.targets.is_empty() {
            Some("no_target_zones")
        } else if report.unserved_targets == 0 {
            Some("all_target_zones_entered_and_centres_near_road")
        } else if report.accepted_segments >= program.max_new_segments {
            Some("segment_budget_exhausted")
        } else if report.attempted_candidates >= program.max_candidate_attempts {
            Some("candidate_budget_exhausted")
        } else if node_levels.is_empty() {
            Some("no_existing_connected_frontier")
        } else {
            None
        };
        if let Some(stop) = stop {
            report.stop_reason = stop.into();
            break;
        }
        let mut candidates = vec![];
        for n in &plan.nodes {
            for [dx, dz] in [[-1, 0], [0, -1], [1, 0], [0, 1]] {
                for &length in &program.segment_lengths_m {
                    let x = i64::from(n.world_x) + i64::from(dx) * i64::from(length);
                    let z = i64::from(n.world_z) + i64::from(dz) * i64::from(length);
                    if x < i64::from(scene.origin_x) + 8
                        || z < i64::from(scene.origin_z) + 8
                        || x + 8 >= i64::from(scene.origin_x) + i64::from(scene.width_m)
                        || z + 8 >= i64::from(scene.origin_z) + i64::from(scene.depth_m)
                    {
                        continue;
                    }
                    let mut c = Candidate {
                        start: [n.world_x, n.world_z],
                        end: [x as i32, z as i32],
                        node: n.id,
                        priority: usize::MAX,
                        served: 0,
                        gain: 0,
                        length,
                        tier_rank: 0,
                        tier_role: None,
                        road_width_m: 8,
                    };
                    if attempted.contains(&c.key()) {
                        continue;
                    }
                    if let Some(hierarchy) = &program.hierarchy {
                        let mut best: Option<(usize, usize, u64, &str, String, u32)> = None;
                        let total_served = report
                            .targets
                            .iter()
                            .filter(|target| {
                                program
                                    .priority_purposes
                                    .iter()
                                    .any(|purpose| purpose == &target.purpose)
                                    && (!target.after_has_road
                                        || target.after_distance_m.is_some_and(|d| {
                                            d > u64::from(program.reach_distance_m)
                                        }))
                            })
                            .filter(|target| {
                                let old = target.after_distance_m.unwrap();
                                let next = old.min(distance(target.centre, c.bounds(0)));
                                next <= u64::from(program.reach_distance_m)
                                    && (target.after_has_road
                                        || intersects(target.zone_bounds, c.bounds(0)))
                            })
                            .count();
                        for (priority, purpose) in program.priority_purposes.iter().enumerate() {
                            let mut purpose_gain = 0_u64;
                            let mut purpose_served = 0_usize;
                            for target in report.targets.iter().filter(|t| {
                                &t.purpose == purpose
                                    && (!t.after_has_road
                                        || t.after_distance_m.is_some_and(|d| {
                                            d > u64::from(program.reach_distance_m)
                                        }))
                            }) {
                                let old = target.after_distance_m.unwrap();
                                let next = old.min(distance(target.centre, c.bounds(0)));
                                let gain = old.saturating_sub(next);
                                let served = next <= u64::from(program.reach_distance_m)
                                    && (target.after_has_road
                                        || intersects(target.zone_bounds, c.bounds(0)));
                                purpose_gain += gain;
                                if served {
                                    purpose_served += 1;
                                }
                            }
                            c.gain += purpose_gain;
                            if purpose_gain == 0 && purpose_served == 0 {
                                continue;
                            }
                            let Some(tier) = hierarchy.tier_for(purpose, total_served >= 2) else {
                                continue;
                            };
                            let candidate = (
                                priority,
                                purpose_served,
                                purpose_gain,
                                purpose.as_str(),
                                tier.role.clone(),
                                tier.width_m,
                            );
                            let better = match &best {
                                None => true,
                                Some((bp, bs, bg, bpurpose, _, _)) => {
                                    priority < *bp
                                        || (priority == *bp
                                            && (purpose_served > *bs
                                                || (purpose_served == *bs
                                                    && (purpose_gain > *bg
                                                        || (purpose_gain == *bg
                                                            && purpose.as_str() < *bpurpose)))))
                                }
                            };
                            if better {
                                best = Some(candidate);
                            }
                        }
                        c.served = total_served;
                        if let Some((priority, _, _, _, role, width_m)) = best {
                            c.priority = priority;
                            c.tier_rank = match role.as_str() {
                                "collector" => 0,
                                "local" => 1,
                                _ => 2,
                            };
                            c.tier_role = Some(role);
                            c.road_width_m = width_m;
                        }
                    } else {
                        for (priority, purpose) in program.priority_purposes.iter().enumerate() {
                            for target in report.targets.iter().filter(|t| {
                                &t.purpose == purpose
                                    && (!t.after_has_road
                                        || t.after_distance_m.is_some_and(|d| {
                                            d > u64::from(program.reach_distance_m)
                                        }))
                            }) {
                                let old = target.after_distance_m.unwrap();
                                let next = old.min(distance(target.centre, c.bounds(0)));
                                c.gain += old - next;
                                if next <= u64::from(program.reach_distance_m)
                                    && (target.after_has_road
                                        || intersects(target.zone_bounds, c.bounds(0)))
                                {
                                    c.served += 1;
                                }
                            }
                            if c.gain > 0 || c.served > 0 {
                                c.priority = priority;
                                break;
                            }
                        }
                    }
                    if c.priority != usize::MAX {
                        candidates.push(c);
                    }
                }
            }
        }
        candidates.sort_by_key(|c| {
            (
                c.priority,
                c.tier_rank,
                Reverse(c.served),
                Reverse(c.gain),
                c.length,
                c.node,
                c.end,
            )
        });
        if candidates.is_empty() {
            report.stop_reason = "no_progress_candidate".into();
            break;
        }
        for c in candidates {
            if report.attempted_candidates >= program.max_candidate_attempts {
                report.stop_reason = "candidate_budget_exhausted".into();
                break 'growth;
            }
            attempted.insert(c.key());
            report.attempted_candidates += 1;
            let id = format!(
                "generated.road-auto.{}.{}",
                scene.scene_id, report.accepted_segments
            );
            let result = (|| {
                clear(&c, plan, &roads, &ctx)?;
                let r = CorridorRequest {
                    scene_id: scene.scene_id.clone(),
                    start: c.start,
                    end: c.end,
                    road_width_m: c.road_width_m,
                    shoulder_width_m: 3,
                    max_fill_mm: 6000,
                    max_rise_mm_per_m: 80,
                    start_level_mm: Some(
                        *node_levels
                            .get(&c.start)
                            .ok_or_else(|| err("missing start node height"))?,
                    ),
                    end_level_mm: node_levels.get(&c.end).copied(),
                    junction_length_m: 8,
                };
                let request = ctx.infer_end(&r)?;
                road_extensions::append_one(plan, &ctx, &request, id.clone())
            })();
            match result {
                Ok(()) => {
                    report.accepted_segments += 1;
                    report.generated_road_ids.push(id);
                    continue 'growth;
                }
                Err(e) => {
                    *report.rejected_by_reason.entry(category(&e.0)).or_default() += 1;
                    if report.rejection_examples.len() < 32 {
                        report.rejection_examples.push(RejectedExample {
                            start: c.start,
                            end: c.end,
                            reason: e.0,
                        });
                    }
                }
            }
        }
        report.stop_reason = "no_feasible_progress_candidate".into();
        break;
    }
    plan.automatic_extensions = Some(report);
    Ok(())
}

/// One candidate road state: a graph node, a cardinal direction, a stated
/// length and a purpose-authorized tier width.
#[derive(Clone, PartialEq, Eq, PartialOrd, Ord)]
struct SupplyState {
    node: usize,
    start: [i32; 2],
    end: [i32; 2],
    length: u32,
    width_m: u32,
    tier_role: String,
}
impl SupplyState {
    fn key(&self) -> [i32; 5] {
        [
            self.start[0],
            self.start[1],
            self.end[0],
            self.end[1],
            self.width_m as i32,
        ]
    }
    fn tier_rank(&self) -> u8 {
        match self.tier_role.as_str() {
            "collector" => 0,
            "local" => 1,
            _ => 2,
        }
    }
}

/// One measured candidate: real parcel supply already counted, the engineering
/// model it was measured on, and the graph state that would be committed.
struct SupplyChoice {
    gains: Vec<usize>,
    total: usize,
    station_attempts: u32,
    state: SupplyState,
    staged: RoadNetworkPlan,
    id: String,
}
impl SupplyChoice {
    /// Deterministic preference: serve the still-outstanding request with the
    /// least coverage first, then the largest real gain, then the cheapest
    /// authorized engineering, then stable graph identity. Distance is not part
    /// of this key.
    fn order(&self) -> (usize, Reverse<usize>, Reverse<usize>, u8, u32, usize, [i32; 2]) {
        (
            self.gains
                .iter()
                .position(|gain| *gain > 0)
                .unwrap_or(usize::MAX),
            Reverse(*self.gains.iter().max().unwrap_or(&0)),
            Reverse(self.total),
            self.state.tier_rank(),
            self.state.length,
            self.state.node,
            self.state.end,
        )
    }
}

/// How version 3 obtains the roads it appends to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SupplyMode {
    /// Run the authored v1/v2 stage first, then append demand-led roads.
    Append,
    /// The earlier semantics: version 3 replaces the authored automatic stage.
    Replace,
}

/// Monotonic millisecond clock. Wall time is a *resource guard*, not the
/// authority: the deterministic counters below decide what a successful plan
/// may contain, and a clock expiry only marks the run incomplete.
pub(super) trait SupplyClock {
    fn millis(&self) -> u64;
}
pub(super) struct WallClock {
    started: Instant,
}
impl WallClock {
    fn start() -> Self {
        Self {
            started: Instant::now(),
        }
    }
}
impl SupplyClock for WallClock {
    fn millis(&self) -> u64 {
        self.started.elapsed().as_millis() as u64
    }
}

/// Version 3: the road that is built is the one that demonstrably adds real,
/// realized-with-access parcels for the outstanding authored demand. Zone
/// proximity only orders the bounded state list; it never earns credit. A
/// candidate is measured cheaply for ordering and then must survive the full
/// realization chain before it may be committed; anything else is rolled back.
/// Outcome of one demand-led append phase.
enum SupplyPhase {
    /// The phase ended on its deterministic contract (demand satisfied or a
    /// work budget) and may be committed.
    Complete(Report),
    /// The wall clock stopped the phase. Nothing may be published: the caller
    /// keeps the trusted baseline and returns a structured incomplete result.
    WallClockAborted {
        stage: &'static str,
        states: usize,
        accepted_roads: usize,
        credited_road_ids: Vec<String>,
    },
}

#[allow(clippy::too_many_arguments)]
fn append_supply_aware(
    plan: &mut RoadNetworkPlan,
    scene: &SceneSpec,
    t: &BakedTerrain,
    water: WaterGeometry,
    zones: &[LandUseZone],
    style: &serde_json::Value,
    program: &SceneProgram,
    mode: SupplyMode,
    clock: &dyn SupplyClock,
    source: NaturalSource,
) -> Result<(), TerrainError> {
    // The whole append phase runs on its own working copy. Only a complete,
    // verified phase is published; a wall-clock stop leaves `plan` exactly as
    // the trusted baseline that entered this phase.
    let mut working = plan.clone();
    match run_supply_phase(
        &mut working, scene, t, water, zones, style, program, mode, clock, source,
    )? {
        SupplyPhase::Complete(report) => {
            working.automatic_extensions = Some(report);
            *plan = working;
            Ok(())
        }
        SupplyPhase::WallClockAborted {
            stage,
            states,
            accepted_roads,
            credited_road_ids,
        } => Err(err(format!(
            "supply_phase_wall_clock_aborted:{}",
            serde_json::json!({
                "stage": stage,
                "candidateStatesExamined": states,
                "acceptedRoadsDiscarded": accepted_roads,
                "creditedRoadsDiscarded": credited_road_ids,
                "authoritative": false,
                "note": "the append phase was rolled back completely; the trusted baseline is unchanged and must not be published as a supply result",
            })
        ))),
    }
}

/// The append phase itself, on a caller-owned working plan.
#[allow(clippy::too_many_arguments)]
fn run_supply_phase(
    plan: &mut RoadNetworkPlan,
    scene: &SceneSpec,
    t: &BakedTerrain,
    water: WaterGeometry,
    zones: &[LandUseZone],
    style: &serde_json::Value,
    program: &SceneProgram,
    mode: SupplyMode,
    clock: &dyn SupplyClock,
    source: NaturalSource,
) -> Result<SupplyPhase, TerrainError> {
    let policy = program
        .supply
        .as_ref()
        .ok_or_else(|| err("version 3 requires a supply policy"))?;
    let hierarchy = program
        .hierarchy
        .as_ref()
        .ok_or_else(|| err("version 3 requires a road hierarchy"))?;
    let budget_ms = policy.preflight_budget_ms;
    let ctx = AlignmentContext::new(scene, t, water, zones)?
        .with_cut(super::bounded_cut::CutPolicy::from_style(style).0.cap_mm());
    let mask = ZoningMask::new(scene, zones)?;
    let supply = SupplyContext {
        scene,
        terrain: t,
        mask: &mask,
        water,
        zones,
        // The road-supply phase runs BEFORE frontage placement, so no pad has a
        // cap yet and the measurement must use the same policy `frontage::append`
        // will read from this world's style.
        policy: super::bounded_cut::CutPolicy::from_style(style).0,
    };
    let base_report = if mode == SupplyMode::Append {
        plan.automatic_extensions.clone().map(Box::new)
    } else {
        None
    };
    // Trusted base contract: derived from the plan's own *ungraded base* domain,
    // which is the production base network of this scene (extensions never
    // mutate it). Its equality with a fresh production rebuild is asserted by
    // the frozen baseline probe, not assumed here.
    let trusted = super::road_parcel_feasibility::trusted_base_contract(
        &base_only_plan(plan)?,
        &t.content_hash()?,
    )
    .map_err(err)?;
    // The trusted baseline is what the world realizes *before* this phase: the
    // candidate plan plus the production frontage selection, measured through
    // the same realization chain. Demand, regression and identity are all
    // judged against this, never against an assumed zero.
    let mut baseline_plan = plan.clone();
    super::frontage::append(&mut baseline_plan, scene, t, water, Some(zones), style)?;
    if clock.millis() >= budget_ms {
        return Ok(SupplyPhase::WallClockAborted {
            stage: "before-baseline-realization",
            states: 0,
            accepted_roads: 0,
            credited_road_ids: vec![],
        });
    }
    let baseline_realization = super::frontage_supply::realize_candidate(
        scene,
        t,
        water,
        zones,
        &baseline_plan,
        source,
        &trusted,
        style,
    )
    .map_err(err)?;
    if clock.millis() >= budget_ms {
        return Ok(SupplyPhase::WallClockAborted {
            stage: "after-baseline-realization",
            states: 0,
            accepted_roads: 0,
            credited_road_ids: vec![],
        });
    }
    let mut session = SupplySession::for_scene(style, &scene.scene_id, &baseline_plan)?;
    // Only truly realized identities may count as satisfied demand, adopted
    // with their exact structured ownership and real geometry.
    session
        .adopt(&baseline_plan, &baseline_realization)
        .map_err(err)?;
    let orders: Vec<String> = session
        .budgets
        .iter()
        .map(|b| b.request.id.clone())
        .collect();
    let mut report = Report {
        version: 1,
        model: "demand-led-realized-parcel-supply-v3".into(),
        scope: "bounded-candidate-states-scored-by-realized-with-access-parcels-not-distance".into(),
        program: program.clone(),
        stop_reason: String::new(),
        attempted_candidates: 0,
        accepted_segments: 0,
        generated_road_ids: vec![],
        targets: vec![],
        unserved_targets: session.remaining_total(),
        rejected_by_reason: BTreeMap::new(),
        rejection_examples: vec![],
        supply: vec![],
        sweep: vec![],
        sweep_exhausted: false,
        base_road_program: base_report,
        incomplete: false,
        incomplete_reason: None,
    };
    let mut attempted_states: BTreeSet<[i32; 5]> = BTreeSet::new();
    loop {
        if session.remaining_total() == 0 {
            report.stop_reason = "demand_satisfied_by_realized_parcels".into();
            break;
        }
        if report.accepted_segments >= program.max_new_segments {
            report.stop_reason = "segment_budget_exhausted".into();
            break;
        }
        if report.attempted_candidates >= program.max_candidate_attempts {
            report.stop_reason = "candidate_budget_exhausted".into();
            break;
        }
        if report.attempted_candidates >= policy.max_candidate_states {
            report.stop_reason = "candidate_state_budget_exhausted".into();
            break;
        }
        if clock.millis() >= budget_ms {
            report.stop_reason = "preflight_budget_exhausted".into();
            report.incomplete = true;
            report.incomplete_reason = Some("wall-clock preflight budget exhausted".into());
            break;
        }
        // Bounded sweep: states are visited in the documented deterministic
        // order until a batch of measured candidates exists, the frozen state
        // budget is spent, or the resource guard trips.
        let mut states = supply_states(
            plan,
            scene,
            program,
            hierarchy,
            &session,
            &attempted_states,
        )?;
        let states_was_nonempty = !states.is_empty();
        states.sort_by_key(|s| {
            (
                supply_order(zones, &session, s),
                s.tier_rank(),
                s.node,
                s.end,
                s.length,
                s.width_m,
            )
        });
        let mut batch: Vec<SupplyChoice> = vec![];
        let mut scanned_empty = true;
        let mut scanned_all = true;
        for state in states {
            if batch.len() >= SUPPLY_BATCH
                || report.attempted_candidates >= policy.max_candidate_states
                || report.attempted_candidates >= program.max_candidate_attempts
                || clock.millis() >= budget_ms
            {
                scanned_all = false;
                break;
            }
            scanned_empty = false;
            report.attempted_candidates += 1;
            attempted_states.insert(state.key());
            let mut staged = plan.clone();
            let roads = staged.entities();
            let node_levels = levels(&staged, &roads)?;
            // Append mode must never reuse the authored automatic stage's
            // identities (auto.0/.1 are taken); its own namespace is explicit.
            let id = match mode {
                SupplyMode::Append => format!(
                    "generated.road-supply.{}.{}",
                    scene.scene_id, report.accepted_segments
                ),
                SupplyMode::Replace => format!(
                    "generated.road-auto.{}.{}",
                    scene.scene_id, report.accepted_segments
                ),
            };
            let appended = (|| -> Result<(), TerrainError> {
                clear(
                    &Candidate {
                        start: state.start,
                        end: state.end,
                        node: state.node,
                        priority: 0,
                        served: 0,
                        gain: 0,
                        length: state.length,
                        tier_rank: 0,
                        tier_role: Some(state.tier_role.clone()),
                        road_width_m: state.width_m,
                    },
                    &staged,
                    &roads,
                    &ctx,
                )?;
                let r = CorridorRequest {
                    scene_id: scene.scene_id.clone(),
                    start: state.start,
                    end: state.end,
                    road_width_m: state.width_m,
                    shoulder_width_m: 3,
                    max_fill_mm: 6000,
                    max_rise_mm_per_m: 80,
                    start_level_mm: Some(
                        *node_levels
                            .get(&state.start)
                            .ok_or_else(|| err("missing start node height"))?,
                    ),
                    end_level_mm: node_levels.get(&state.end).copied(),
                    junction_length_m: 8,
                };
                let request = ctx.infer_end(&r)?;
                road_extensions::append_one(&mut staged, &ctx, &request, id.clone())
            })();
            if let Err(e) = appended {
                *report.rejected_by_reason.entry(category(&e.0)).or_default() += 1;
                report.sweep.push(SupplySweepEntry {
                    start: state.start,
                    end: state.end,
                    width_m: state.width_m,
                    outcome: "road_refused".into(),
                    parcels: 0,
                    station_attempts: 0,
                    first_reason: e.0.clone(),
                    first_parcel: vec![],
                    first_conflicting_entity: String::new(),
                    first_before_mm: 0,
                    first_after_mm: 0,
                    rejected: BTreeMap::new(),
                });
                if report.rejection_examples.len() < 32 {
                    report.rejection_examples.push(RejectedExample {
                        start: state.start,
                        end: state.end,
                        reason: e.0,
                    });
                }
                continue;
            }
            // Measurement copy: already-realized parcels are occupied ground;
            // the committed plan itself stays roads-only so the bake re-derives
            // them from the same placement rules.
            let mut probe = staged.clone();
            probe
                .roadside_sites
                .extend(session.occupied());
            let road = probe
                .entities()
                .into_iter()
                .find(|e| e.entity_id == id)
                .ok_or_else(|| err("staged supply road missing"))?;
            let mut trial = session.clone();
            let before = trial.realized_totals();
            let mut traces = vec![];
            for index in 0..trial.budgets.len() {
                if trial.budgets[index].satisfied() || !trial.budgets[index].budget_left() {
                    continue;
                }
                let measured = supply.measure_road_for_request(
                    &probe,
                    &road,
                    &mut trial.budgets[index],
                    SUPPLY_SAMPLE_CAP,
                )?;
                traces.push(measured.trace);
            }
            let gains: Vec<usize> = trial
                .realized_totals()
                .iter()
                .zip(&before)
                .map(|((_, after), (_, prior))| after.saturating_sub(*prior))
                .collect();
            let total: usize = gains.iter().sum();
            let attempts: u32 = traces.iter().map(|trace| trace.attempted).sum();
            let first = traces
                .iter()
                .find_map(|trace| {
                    let detail = trace.rejection_details.first()?;
                    Some((
                        detail.reason.clone(),
                        trace.rejected.clone(),
                        detail.note.clone().unwrap_or_default(),
                        detail.conflicting_entity.clone().unwrap_or_default(),
                        detail.before_mm,
                        detail.after_mm,
                    ))
                })
                .unwrap_or_else(|| {
                    (
                        "no_station".into(),
                        BTreeMap::new(),
                        String::new(),
                        String::new(),
                        None,
                        None,
                    )
                });
            report.sweep.push(SupplySweepEntry {
                start: state.start,
                end: state.end,
                width_m: state.width_m,
                outcome: if total == 0 {
                    "no_real_parcel_supply".into()
                } else {
                    "measured_real_parcel_supply".into()
                },
                parcels: total,
                station_attempts: attempts,
                first_reason: first.0.clone(),
                first_parcel: first
                    .2
                    .trim_start_matches("parcel=[")
                    .trim_end_matches(']')
                    .split(',')
                    .filter_map(|value| value.parse::<i64>().ok())
                    .collect(),
                first_conflicting_entity: first.3.clone(),
                first_before_mm: i64::from(first.4.unwrap_or(0)),
                first_after_mm: i64::from(first.5.unwrap_or(0)),
                rejected: first.1.clone(),
            });
            if total == 0 {
                *report
                    .rejected_by_reason
                    .entry("no_real_parcel_supply".into())
                    .or_default() += 1;
                if report.rejection_examples.len() < 32 {
                    report.rejection_examples.push(RejectedExample {
                        start: state.start,
                        end: state.end,
                        reason: format!(
                            "no_real_parcel_supply: {} after {} stations",
                            first.0, attempts
                        ),
                    });
                }
                continue;
            }
            batch.push(SupplyChoice {
                gains,
                total,
                station_attempts: attempts,
                state,
                staged,
                id,
            });
        }
        if batch.is_empty() {
            report.sweep_exhausted = scanned_all && states_was_nonempty;
            if clock.millis() >= budget_ms {
                return Ok(SupplyPhase::WallClockAborted {
                    stage: "mid-sweep",
                    states: report.attempted_candidates,
                    accepted_roads: report.accepted_segments,
                    credited_road_ids: report.generated_road_ids.clone(),
                });
            }
            report.stop_reason = if scanned_empty {
                "no_untried_candidate_state".into()
            } else if report.attempted_candidates >= policy.max_candidate_states {
                "candidate_state_budget_exhausted".into()
            } else {
                "no_real_supply_in_bounded_sweep".into()
            };
            break;
        }
        batch.sort_by_key(|choice| choice.order());
        let mut committed_this_round = false;
        for choice in batch {
            let SupplyChoice {
                gains,
                station_attempts,
                state,
                staged,
                id,
                ..
            } = choice;
            if clock.millis() >= budget_ms {
                // A resource limit may never publish a success prefix, and the
                // whole phase is rolled back by the caller.
                return Ok(SupplyPhase::WallClockAborted {
                    stage: "before-candidate-realization",
                    states: report.attempted_candidates,
                    accepted_roads: report.accepted_segments,
                    credited_road_ids: report.generated_road_ids.clone(),
                });
            }
            // The staged plan for realization: committed roads plus the
            // candidate, with the production frontage selection materialized so
            // the realization audits can see the planned parcels.
            let mut verification = staged.clone();
            if let Err(error) = super::frontage::append(
                &mut verification,
                scene,
                t,
                water,
                Some(zones),
                style,
            )
            {
                *report
                    .rejected_by_reason
                    .entry("frontage_verification_rejected".into())
                    .or_default() += 1;
                report.rejection_examples.push(RejectedExample {
                    start: state.start,
                    end: state.end,
                    reason: format!("frontage verification refused the staged road: {}", error.0),
                });
                continue;
            }
            // The real realization chain on the candidate's own final raster.
            let realization = match super::frontage_supply::realize_candidate(
                scene, t, water, zones, &verification, source, &trusted, style,
            ) {
                Ok(realization) => realization,
                Err(reason) => {
                    *report.rejected_by_reason.entry(reason).or_default() += 1;
                    report.rejection_examples.push(RejectedExample {
                        start: state.start,
                        end: state.end,
                        reason: "realization chain refused the staged road".into(),
                    });
                    continue;
                }
            };
            if clock.millis() >= budget_ms {
                // The realization crossed the limit: nothing is committed.
                return Ok(SupplyPhase::WallClockAborted {
                    stage: "during-candidate-realization",
                    states: report.attempted_candidates,
                    accepted_roads: report.accepted_segments,
                    credited_road_ids: report.generated_road_ids.clone(),
                });
            }
            if let Err(reason) =
                commit_decision(
                    &session,
                    &realization,
                    &baseline_realization,
                    &verification,
                )
            {
                *report.rejected_by_reason.entry(reason).or_default() += 1;
                report.rejection_examples.push(RejectedExample {
                    start: state.start,
                    end: state.end,
                    reason: "rollback: realized credit did not survive verification".into(),
                });
                continue;
            }
            let realized_increments: Vec<usize> = realized_increments(&session, &realization);
            let shortfall = realized_increments
                .iter()
                .zip(&gains)
                .any(|(realized, predicted)| realized < predicted);
            // Adopt the verified identities atomically; a failure here rolls the
            // candidate back like any other verification failure.
            if let Err(reason) = session.adopt(&verification, &realization) {
                *report.rejected_by_reason.entry(reason).or_default() += 1;
                report.rejection_examples.push(RejectedExample {
                    start: state.start,
                    end: state.end,
                    reason: "rollback: commitment adoption failed".into(),
                });
                continue;
            }
            report.accepted_segments += 1;
            report.generated_road_ids.push(id.clone());
            report.supply.push(SupplyRoadEvidence {
                road_id: id,
                requests: orders.clone(),
                predicted_gains: gains,
                verified_gains: realized_increments,
                station_attempts,
                cumulative_candidate_states: report.attempted_candidates,
                planned: realization.planned,
                realized_with_access: realization.realized_with_access,
                yard_unresolved_m2: realization.yard_unresolved_m2,
                road_status: realization.road_status.clone(),
                development_status: realization.development_status.clone(),
                landcover_status: realization.landcover_status.clone(),
                outcome: if shortfall {
                    "realized_and_committed_with_shortfall".into()
                } else {
                    "realized_and_committed".into()
                },
            });
            // Only the roads are committed; the frontage selection is re-derived
            // by the final production pass from the same deterministic rules.
            *plan = staged;
            committed_this_round = true;
            break;
        }
        if !committed_this_round {
            if report.attempted_candidates >= policy.max_candidate_states
                || report.attempted_candidates >= program.max_candidate_attempts
            {
                report.stop_reason = "candidate_state_budget_exhausted".into();
                break;
            }
            if clock.millis() >= budget_ms {
                return Ok(SupplyPhase::WallClockAborted {
                    stage: "after-rollbacks",
                    states: report.attempted_candidates,
                    accepted_roads: report.accepted_segments,
                    credited_road_ids: report.generated_road_ids.clone(),
                });
            }
            // Every candidate in the batch failed real verification; sweep on.
        }
    }
    report.unserved_targets = session.remaining_total();
    for (index, request) in session.budgets.iter().enumerate() {
        if request.remaining() > 0 {
            report.rejection_examples.push(RejectedExample {
                start: [0, 0],
                end: [0, 0],
                reason: format!(
                    "unfilled {}: {} of {} parcels have no verified location",
                    orders[index],
                    request.remaining(),
                    request.request.count
                ),
            });
        }
    }
    // The phase is complete: a deterministic contract ended it. The caller
    // publishes this report only after the pre-write-back deadline check.
    if clock.millis() >= budget_ms {
        return Ok(SupplyPhase::WallClockAborted {
            stage: "before-write-back",
            states: report.attempted_candidates,
            accepted_roads: report.accepted_segments,
            credited_road_ids: report.generated_road_ids.clone(),
        });
    }
    Ok(SupplyPhase::Complete(report))
}

/// Bounded candidate states: graph nodes, cardinal directions, stated lengths,
/// and only the tiers the hierarchy authorizes for a still-outstanding purpose.
fn supply_states(
    plan: &RoadNetworkPlan,
    scene: &SceneSpec,
    program: &SceneProgram,
    hierarchy: &RoadHierarchy,
    session: &SupplySession,
    attempted: &BTreeSet<[i32; 5]>,
) -> Result<Vec<SupplyState>, TerrainError> {
    // Every tier authorized for an outstanding purpose is a candidate. Taking
    // only the first tier (which is local for urban) made collector roads
    // unreachable in the demand-led phase even when the hierarchy authorized
    // them. The measured supply, not the tier name, decides which road wins.
    let mut tiers: Vec<(u8, String, u32)> = vec![];
    for request in session.budgets.iter().filter(|b| b.remaining() > 0) {
        let mut authorized: Vec<_> = hierarchy
            .tiers
            .iter()
            .filter(|tier| {
                tier.purposes
                    .iter()
                    .any(|purpose| purpose == &request.request.purpose)
            })
            .collect();
        authorized.sort_by_key(|tier| match tier.role.as_str() {
            "collector" => 0_u8,
            "local" => 1,
            _ => 2,
        });
        if authorized.is_empty() {
            return Err(err("outstanding purpose has no authorized tier"));
        }
        for tier in authorized {
            let rank = match tier.role.as_str() {
                "collector" => 0_u8,
                "local" => 1,
                _ => 2,
            };
            if !tiers
                .iter()
                .any(|(_, role, width)| *role == tier.role && *width == tier.width_m)
            {
                tiers.push((rank, tier.role.clone(), tier.width_m));
            }
        }
    }
    tiers.sort();
    // A segment whose endpoints are already an edge of the network is not a
    // candidate at all: that road exists. Excluding it keeps the frozen state
    // budget for real alternatives instead of spending it on duplicates.
    let existing: BTreeSet<([i32; 2], [i32; 2])> = plan
        .edges
        .iter()
        .filter_map(|edge| {
            let from = plan.nodes.iter().find(|n| n.id == edge.from)?;
            let to = plan.nodes.iter().find(|n| n.id == edge.to)?;
            Some((
                [from.world_x, from.world_z],
                [to.world_x, to.world_z],
            ))
        })
        .collect();
    let mut states = vec![];
    for node in &plan.nodes {
        for [dx, dz] in [[-1_i32, 0_i32], [0, -1], [1, 0], [0, 1]] {
            for &length in &program.segment_lengths_m {
                let x = i64::from(node.world_x) + i64::from(dx) * i64::from(length);
                let z = i64::from(node.world_z) + i64::from(dz) * i64::from(length);
                if x < i64::from(scene.origin_x) + 8
                    || z < i64::from(scene.origin_z) + 8
                    || x + 8 >= i64::from(scene.origin_x) + i64::from(scene.width_m)
                    || z + 8 >= i64::from(scene.origin_z) + i64::from(scene.depth_m)
                {
                    continue;
                }
                let start = [node.world_x, node.world_z];
                let end = [x as i32, z as i32];
                if existing.contains(&(start, end)) || existing.contains(&(end, start)) {
                    continue;
                }
                for (_, role, width_m) in &tiers {
                    let state = SupplyState {
                        node: node.id,
                        start,
                        end,
                        length,
                        width_m: *width_m,
                        tier_role: role.clone(),
                    };
                    // A state is tried at most once in the whole sweep: the
                    // cumulative budget may not be multiplied by re-runs.
                    if attempted.contains(&state.key()) {
                        continue;
                    }
                    states.push(state);
                }
            }
        }
    }
    Ok(states)
}

/// Deterministic ordering only: how close the candidate is to land of a still
/// outstanding purpose. This is never parcel credit.
fn supply_order(zones: &[LandUseZone], session: &SupplySession, state: &SupplyState) -> i64 {
    let midpoint = [
        (i64::from(state.start[0]) + i64::from(state.end[0])) / 2,
        (i64::from(state.start[1]) + i64::from(state.end[1])) / 2,
    ];
    let mut best = i64::MAX;
    for request in session.budgets.iter().filter(|b| b.remaining() > 0) {
        for zone in zones.iter().filter(|z| z.kind == request.request.purpose) {
            let x = midpoint[0];
            let z = midpoint[1];
            let dx = (i64::from(zone.world_x) - x)
                .max(x - (i64::from(zone.world_x) + i64::from(zone.width_m)))
                .max(0);
            let dz = (i64::from(zone.world_z) - z)
                .max(z - (i64::from(zone.world_z) + i64::from(zone.depth_m)))
                .max(0);
            best = best.min(dx + dz);
        }
    }
    best
}

/// Identity of the frontage sites that already existed before this phase: their
/// stable id and full normalized geometry. Regression is judged against these,
/// never against a total count alone.
/// The plan's BASE road domain: every edge that belongs to the base network by
/// planning provenance rather than by the presence or absence of a profile,
/// with the nodes those edges use.
///
/// B01-T2 C3: before T2 a base road never carried a profile, so "ungraded" and
/// "base" happened to coincide and the old predicate was really testing
/// `profile.is_none()`. Once base roads carry their own authoritative profile
/// that test excludes the whole base network, and every downstream consumer that
/// relied on it silently sees an empty base domain. Identity is now:
///   * NOT a member of `plan.extensions` (roads ADDED by the extension phase), and
///   * NOT a road this plan already reported as automatic (roads ADDED by the
///     supply/auto phase, recorded by id in `plan.automatic_extensions`).
/// Everything else is the base network the trusted contract is derived from.
pub(super) fn base_only_plan(plan: &RoadNetworkPlan) -> Result<RoadNetworkPlan, TerrainError> {
    let extension_ids: BTreeSet<&str> = plan
        .extensions
        .iter()
        .map(|extension| extension.entity_id.as_str())
        .collect();
    let automatic_ids: BTreeSet<&str> = plan
        .automatic_extensions
        .as_ref()
        .map(|report| {
            report
                .generated_road_ids
                .iter()
                .map(String::as_str)
                .collect()
        })
        .unwrap_or_default();
    let mut base = plan.clone();
    base.edges.retain(|edge| {
        !extension_ids.contains(edge.id.as_str()) && !automatic_ids.contains(edge.id.as_str())
    });
    if base.edges.is_empty() {
        return Err(err("supply phase needs a base road domain"));
    }
    let keep: BTreeSet<usize> = base.edges.iter().flat_map(|e| [e.from, e.to]).collect();
    base.nodes.retain(|node| keep.contains(&node.id));
    base.extensions.clear();
    base.roadside_sites.clear();
    base.frontage = None;
    base.automatic_extensions = None;
    base.joint_layout = None;
    Ok(base)
}

/// Realized-with-access increments of one verification against the trusted
/// baseline, matched by request id rather than by position.
fn realized_increments(session: &SupplySession, realization: &Realization) -> Vec<usize> {
    session
        .budgets
        .iter()
        .map(|budget| {
            let before: BTreeSet<&String> = budget.site_ids.iter().collect();
            let after = realization
                .realized_ids_by_request
                .iter()
                .find(|(id, _)| *id == budget.request.id)
                .map(|(_, ids)| ids.iter().filter(|id| !before.contains(id)).count())
                .unwrap_or(0);
            after
        })
        .collect()
}

/// The transaction guard: a candidate may only be committed when the accepted
/// realization adds at least one parcel, no request loses realized parcels, no
/// existing frontage identity changes, and no realization signal (yard
/// surfaces, landcover, development ownership, road engineering, access graph,
/// node elevations) is worse than the trusted baseline. Pure over its inputs so
/// the injection tests can drive it directly.
/// The commit gate, visible to the sibling supply module so its bounded
/// production-derived fixture can drive the real guard.
pub(super) fn commit_decision(
    session: &SupplySession,
    realization: &Realization,
    baseline: &Realization,
    verified: &RoadNetworkPlan,
) -> Result<(), String> {
    // 1. Every identity this session has already committed — the entering
    //    baseline and each earlier round of this same phase — must survive with
    //    unchanged geometry and access.
    for (id, expected) in &session.commitments {
        let site = verified
            .roadside_sites
            .iter()
            .find(|site| &site.id == id)
            .ok_or_else(|| format!("realization_lost_existing_site:{id}"))?;
        let mut entity = site.entity();
        entity.normalize_spatial_semantics();
        entity.bounds = None;
        if serde_json::to_value(&entity).ok().as_ref() != Some(expected) {
            return Err(format!("realization_changed_existing_site:{id}"));
        }
        if !realization.realized_ids.iter().any(|realized| realized == id) {
            return Err(format!("realization_lost_existing_access:{id}"));
        }
    }
    // 2. No request may regress, matched by request id.
    for budget in &session.budgets {
        let before = budget.site_ids.len();
        let after = realization
            .realized_by_request
            .iter()
            .find(|(id, _)| *id == budget.request.id)
            .map(|(_, count)| *count)
            .unwrap_or(0);
        if after < before {
            return Err(format!(
                "realization_regressed_request:{}:{}->{}",
                budget.request.id, before, after
            ));
        }
    }
    // 3. Something must actually be newly realized.
    let increments = realized_increments(session, realization);
    if increments.iter().all(|gain| *gain == 0) {
        return Err("realization_added_no_parcels".into());
    }
    // 4. No planned parcel may remain unrealized on the final raster: planning
    //    credit is not implementation credit.
    if realization.planned != realization.realized_with_access {
        return Err(format!(
            "realization_planned_but_not_realized:{}->{}",
            realization.planned, realization.realized_with_access
        ));
    }
    if realization
        .frontage_failures
        .iter()
        .any(|failure| failure.starts_with("frontage building missing/changed/disconnected"))
    {
        return Err(format!(
            "realization_frontage_id_failed:{:?}",
            realization.frontage_failures
        ));
    }
    // 5. Surfaces, ownership, roads, access and node elevations. Every signal is
    //    compared against the trusted baseline: a candidate may not introduce a
    //    failure the baseline did not already have.
    // 5a. Yard shortfall is accounted per owning parcel against the trusted
    //     entering baseline. "Old" means every parcel that already existed
    //     before this phase — the full development asset set, not only the
    //     frontage requests — plus every parcel an earlier round of this same
    //     phase committed. An old parcel may not gain shortfall against its own
    //     protected value (parcels are compared individually, so repairing one
    //     old parcel can never buy room for another), a baseline asset may not
    //     change owner or vanish from the audit map, and a genuinely new parcel
    //     must be fully resolved.
    let mut new_yard_unresolved = 0_f64;
    for (entity_id, parcel) in &realization.parcel_by_entity {
        let shortfall = realization
            .yard_unresolved_by_parcel
            .get(parcel)
            .copied()
            .unwrap_or(0.);
        match session
            .protected_owners
            .get(entity_id)
            .map(|owner| (owner, session.protected_parcels.get(owner).copied()))
        {
            Some((owner, allowance)) => {
                if owner != parcel {
                    return Err(format!(
                        "realization_existing_owner_changed:{entity_id}:{owner}->{parcel}"
                    ));
                }
                let allowance = allowance.unwrap_or(0.);
                if shortfall > allowance + 1e-7 {
                    return Err(format!(
                        "realization_existing_parcel_yard_grew:{parcel}:{allowance}->{shortfall}"
                    ));
                }
            }
            None => {
                if session.commitments.contains_key(entity_id) {
                    return Err(format!(
                        "realization_committed_parcel_unprotected:{entity_id}"
                    ));
                }
                new_yard_unresolved += shortfall;
            }
        }
    }
    // A baseline asset may not disappear from the audit map either: an absent
    // entry is not evidence that its shortfall was resolved.
    for (entity_id, parcel) in &session.protected_owners {
        match realization.parcel_by_entity.get(entity_id) {
            None => {
                return Err(format!(
                    "realization_baseline_asset_missing:{entity_id}"
                ))
            }
            Some(current) if current != parcel => {
                return Err(format!(
                    "realization_existing_owner_changed:{entity_id}:{parcel}->{current}"
                ))
            }
            Some(_) => {}
        }
    }
    if new_yard_unresolved > 1e-7 {
        return Err(format!(
            "realization_new_parcel_yard_unresolved:{new_yard_unresolved}"
        ));
    }
    // A missing or rejected landcover audit leaves an empty per-parcel map,
    // which must not read as "every yard resolved".
    if realization.landcover_status.contains("rejected")
        || realization.landcover_status == "unplanned"
    {
        return Err(format!(
            "realization_landcover_audit_unavailable:{}",
            realization.landcover_status
        ));
    }
    if realization.unresolved_area_m2 > baseline.unresolved_area_m2 + 1e-7 {
        return Err(format!(
            "realization_surface_unresolved:{}->{}",
            baseline.unresolved_area_m2, realization.unresolved_area_m2
        ));
    }
    if baseline.landcover_status == "pass" && realization.landcover_status != "pass"
        || realization.landcover_status == "fail"
    {
        return Err(format!(
            "realization_landcover_failed:{}->{}",
            baseline.landcover_status, realization.landcover_status
        ));
    }
    let new_landcover_failures: Vec<&String> = realization
        .landcover_failures
        .iter()
        .filter(|failure| !baseline.landcover_failures.contains(failure))
        .collect();
    if !new_landcover_failures.is_empty() {
        return Err(format!(
            "realization_landcover_new_failure:{:?}",
            new_landcover_failures
        ));
    }
    if baseline.development_status == "pass" && realization.development_status != "pass"
        || realization.development_status == "fail"
    {
        return Err(format!(
            "realization_development_failed:{}->{}",
            baseline.development_status, realization.development_status
        ));
    }
    let new_development_failures: Vec<&String> = realization
        .development_failures
        .iter()
        .filter(|failure| !baseline.development_failures.contains(failure))
        .collect();
    if !new_development_failures.is_empty() {
        return Err(format!(
            "realization_development_new_failure:{:?}",
            new_development_failures
        ));
    }
    if realization.program_landcover_status != "pass" {
        return Err(format!(
            "realization_program_landcover_failed:{}",
            realization.program_landcover_status
        ));
    }
    let new_road_failures: Vec<&String> = realization
        .road_failures
        .iter()
        .filter(|failure| !baseline.road_failures.contains(failure))
        .collect();
    if !new_road_failures.is_empty() {
        return Err(format!(
            "realization_road_failed:{:?}",
            new_road_failures
        ));
    }
    if realization.node_status != "pass" {
        return Err(format!(
            "realization_node_height_failed:{}",
            realization.node_status
        ));
    }
    let new_unconnected: Vec<&String> = realization
        .required_unconnected_ids
        .iter()
        .filter(|id| !baseline.required_unconnected_ids.contains(id))
        .collect();
    if !new_unconnected.is_empty() {
        return Err(format!(
            "realization_required_access_missing:{}",
            new_unconnected
                .iter()
                .map(|id| id.as_str())
                .collect::<Vec<_>>()
                .join(",")
        ));
    }
    Ok(())
}

