    #[test]
    fn automatically_reaches_target_without_coordinates_or_level_inputs() {
        let (s, t, w, z, mut p, style) = fixture();
        let before = p.entities();
        append(&mut p, &s, &t, w, &z, &style).unwrap();
        let a = p.automatic_extensions.as_ref().unwrap();
        assert_eq!(
            a.stop_reason,
            "all_target_zones_entered_and_centres_near_road"
        );
        assert_eq!(a.unserved_targets, 0);
        assert!(a.accepted_segments >= 2);
        assert_eq!(a.generated_road_ids.len(), a.accepted_segments);
        assert_eq!(
            serde_json::to_value(before).unwrap(),
            serde_json::to_value(&p.entities()[..1]).unwrap()
        );
        assert!(
            p.extensions
                .iter()
                .any(|e| e.design.request.start_level_mm != e.design.request.end_level_mm)
        );
        let mut repeated = fixture().4;
        append(&mut repeated, &s, &t, w, &z, &style).unwrap();
        assert_eq!(
            serde_json::to_value(p).unwrap(),
            serde_json::to_value(repeated).unwrap()
        );
    }
    #[test]
    fn explicit_hierarchy_selects_actual_collector_and_local_widths() {
        let (s, t, w, z, mut p, mut style) = fixture();
        style["automaticRoadExtensions"]["version"] = serde_json::json!(2);
        style["automaticRoadExtensions"]["scenes"][0]["segmentLengthsM"] =
            serde_json::json!([384, 128, 64]);
        style["automaticRoadExtensions"]["scenes"][0]["priorityPurposes"] =
            serde_json::json!(["urban", "rural"]);
        style["automaticRoadExtensions"]["scenes"][0]["hierarchy"] = serde_json::json!({
            "tiers": [
                {"id":"collector-16","role":"collector","widthM":16,"purposes":["urban","rural"]},
                {"id":"local-12","role":"local","widthM":12,"purposes":["urban"]},
                {"id":"farm-8","role":"farm_access","widthM":8,"purposes":["rural"]}
            ]
        });
        append(&mut p, &s, &t, w, &z, &style).unwrap();
        let hierarchy = RoadHierarchy {
            tiers: vec![
                RoadTier {
                    id: "collector-16".into(),
                    role: "collector".into(),
                    width_m: 16,
                    purposes: vec!["urban".into(), "rural".into()],
                },
                RoadTier {
                    id: "local-12".into(),
                    role: "local".into(),
                    width_m: 12,
                    purposes: vec!["urban".into()],
                },
                RoadTier {
                    id: "farm-8".into(),
                    role: "farm_access".into(),
                    width_m: 8,
                    purposes: vec!["rural".into()],
                },
            ],
        };
        assert_eq!(hierarchy.tier_for("urban", true).unwrap().role, "collector");
        assert_eq!(hierarchy.tier_for("urban", false).unwrap().width_m, 12);
        assert_eq!(hierarchy.tier_for("rural", false).unwrap().width_m, 8);
        let widths: BTreeSet<_> = p
            .extensions
            .iter()
            .map(|e| e.design.request.road_width_m)
            .collect();
        assert!(widths.contains(&16), "{widths:?}");
        for extension in &p.extensions {
            let entity = p
                .entities()
                .into_iter()
                .find(|e| e.entity_id == extension.entity_id)
                .unwrap();
            assert_eq!(entity.depth_m, extension.design.request.road_width_m as f32);
            entity
                .grounding
                .road_profile
                .as_ref()
                .unwrap()
                .validate_entity(&entity)
                .unwrap();
        }
    }
