    #[test]
    fn automatic_growth_is_translation_covariant_for_nonzero_origins() {
        let (s, t, w, z, p, style) = fixture();
        let mut first = p.clone();
        append(&mut first, &s, &t, w, &z, &style).unwrap();
        let (ox, oz) = (-1_000_000, 2_000_000);
        let mut shifted = s.clone();
        shifted.origin_x = ox;
        shifted.origin_z = oz;
        let bytes = encode_millimetres(
            512,
            512,
            (0..512)
                .flat_map(|zz| (0..512).map(move |xx| (xx, zz)))
                .map(|(x, z)| f64::from(t.height_millimetres(x, z).unwrap()) / 1000.),
        )
        .unwrap();
        let mut raster = BakedTerrain::new(&shifted).unwrap();
        raster.insert_chunk(ox, oz, 512, 512, &bytes).unwrap();
        let mut zones = z.clone();
        for q in &mut zones {
            q.world_x += ox;
            q.world_z += oz;
        }
        let mut plan = p;
        for n in &mut plan.nodes {
            n.world_x += ox;
            n.world_z += oz;
        }
        for e in &mut plan.edges {
            e.world_x += ox;
            e.world_z += oz;
        }
        plan.natural_heightfield_hash = raster.content_hash().unwrap();
        append(&mut plan, &shifted, &raster, w, &zones, &style).unwrap();
        assert_eq!(first.extensions.len(), plan.extensions.len());
        for (a, b) in first.extensions.iter().zip(&plan.extensions) {
            assert_eq!(a.design.profile_mm, b.design.profile_mm);
            assert_eq!(
                a.design.request.start,
                [
                    b.design.request.start[0] - ox,
                    b.design.request.start[1] - oz
                ]
            );
            assert_eq!(
                a.design.request.end,
                [b.design.request.end[0] - ox, b.design.request.end[1] - oz]
            );
        }
        let a = first.automatic_extensions.unwrap();
        let b = plan.automatic_extensions.unwrap();
        assert_eq!(a.stop_reason, b.stop_reason);
        assert_eq!(a.attempted_candidates, b.attempted_candidates);
        assert_eq!(
            a.targets
                .iter()
                .map(|t| t.after_distance_m)
                .collect::<Vec<_>>(),
            b.targets
                .iter()
                .map(|t| t.after_distance_m)
                .collect::<Vec<_>>()
        );
    }

    /// Independent demand-led fixture. Terrain is flat except two ridges that
    /// leave the east corridor buildable but give its parcels no legal ground.
    fn supply_fixture() -> (
        SceneSpec,
        BakedTerrain,
        WaterGeometry,
        Vec<LandUseZone>,
        RoadNetworkPlan,
        serde_json::Value,
    ) {
        supply_fixture_with_id("supply")
    }

    fn supply_fixture_with_id(scene_id: &str) -> (
        SceneSpec,
        BakedTerrain,
        WaterGeometry,
        Vec<LandUseZone>,
        RoadNetworkPlan,
        serde_json::Value,
    ) {
        let s = SceneSpec {
            scene_id: scene_id.into(),
            width_m: 256,
            depth_m: 256,
            origin_x: 0,
            origin_z: 0,
            seed_offset: 0,
        };
        let mut t = BakedTerrain::new(&s).unwrap();
        let mut values = vec![-2.123_f64; 256 * 256];
        // Ridges cover exactly the east corridor's building pads while leaving
        // its graded band, its automatic endpoint platform and the parallel
        // north-south corridor untouched.
        for (z0, z1) in [(104_i32, 118_i32), (138, 152)] {
            for z in z0..=z1 {
                for x in 104..=170_i32 {
                    values[(z * 256 + x) as usize] = 3.0;
                }
            }
        }
        t.insert_chunk(0, 0, 256, 256, &encode_millimetres(256, 256, values).unwrap())
            .unwrap();
        let water = super::super::water_geometry(
            super::super::WaterKind::None,
            &[],
            &s,
            &serde_json::Value::Null,
        );
        let zones = vec![
            LandUseZone {
                id: "rural-west".into(),
                kind: "rural".into(),
                world_x: 0,
                world_z: 0,
                width_m: 64,
                depth_m: 256,
                source: "test".into(),
            },
            LandUseZone {
                id: "urban-east".into(),
                kind: "urban".into(),
                world_x: 64,
                world_z: 0,
                width_m: 192,
                depth_m: 256,
                source: "test".into(),
            },
        ];
        let plan: RoadNetworkPlan = serde_json::from_value(serde_json::json!({
            "model": "fixture",
            "naturalHeightfieldHash": t.content_hash().unwrap(),
            "sceneId": scene_id,
            "status": "planned_connected_network",
            "gridSpacingM": 64,
            "maxRoadbedFillM": 6,
            "levelM": -2,
            "candidates": 1,
            "rejectedWater": 0,
            "rejectedRelief": 0,
            "unselectedCandidates": 0,
            "nodes": [{"id": 0, "worldX": 32, "worldZ": 128}, {"id": 1, "worldX": 96, "worldZ": 128}],
            "edges": [{"id": "base", "from": 0, "to": 1, "worldX": 64, "worldZ": 128, "lengthM": 64, "rotationYDeg": 0, "naturalMinM": -2.1, "naturalMaxM": -2.1}],
            "roadsideSites": []
        }))
        .unwrap();
        let style = serde_json::json!({
            "frontageProgram": {"version": 1, "requests": [{
                "id": "homes",
                "sceneId": scene_id,
                "purpose": "urban",
                "kind": "residential_home",
                "count": 2,
                "widthM": 12,
                "depthM": 10,
                "heightM": 8,
                "stationSpacingM": 24,
                "setbackM": 8,
                "maxCandidateAttempts": 256,
                "parcelInsets": {"frontM": 4, "sideM": 2, "rearM": 4}
            }]},
            "automaticRoadExtensions": {"version": 2, "scenes": [{
                "sceneId": scene_id,
                "maxNewSegments": 2,
                "maxCandidateAttempts": 64,
                "segmentLengthsM": [64],
                "priorityPurposes": ["urban"],
                "reachDistanceM": 32,
                "hierarchy": {"tiers": [
                    {"id": "collector-16", "role": "collector", "widthM": 16, "purposes": ["urban"]},
                    {"id": "local-12", "role": "local", "widthM": 12, "purposes": ["urban"]}
                ]},
            }]},
        });
        (s, t, water, zones, plan, style)
    }

    fn supply_style(style: &serde_json::Value, states: usize) -> serde_json::Value {
        let mut style = style.clone();
        style["automaticRoadExtensions"]["version"] = serde_json::json!(3);
        style["automaticRoadExtensions"]["scenes"][0]["supply"] = serde_json::json!({
            "version": 1,
            "maxCandidateStates": states,
            "preflightBudgetMs": 180000,
            "mode": "append",
        });
        style
    }

    /// A small *production natural* scene: the raster is exactly what the bake's
    /// own encoder produces for the effective seed, and the scene carries a
    /// non-zero `seedOffset`, so the declared context is the only thing that can
    /// reproduce the surface. Returns the effective seed
    /// (`world.seed ^ scene.seedOffset`) as well.
    fn authored_fixture(scene_id: &str) -> (
        SceneSpec,
        BakedTerrain,
        WaterGeometry,
        Vec<LandUseZone>,
        serde_json::Value,
        u64,
    ) {
        // `world.seed ^ scene.seedOffset` is the effective seed; keeping the
        // world seed zero makes the effective seed exactly the offset, which is
        // both non-zero here and a field the production roads can actually be
        // built on.
        let world_seed = 0_u64;
        let seed_offset = 42_u64;
        let seed = world_seed ^ seed_offset;
        assert_ne!(seed_offset, 0);
        assert_ne!(seed, 0);
        let s = SceneSpec {
            scene_id: scene_id.into(),
            width_m: 512,
            depth_m: 512,
            origin_x: 0,
            origin_z: 0,
            seed_offset,
        };
        let w = super::super::water_geometry(
            super::super::WaterKind::None,
            &[],
            &s,
            &serde_json::Value::Null,
        );
        let natural = super::super::generate_chunk_encoded(
            seed, 0, 0, 512, 512, w, &[], true, None,
        )
        .0;
        let mut t = BakedTerrain::new(&s).unwrap();
        t.insert_chunk(0, 0, 512, 512, &natural).unwrap();
        let zones = vec![
            LandUseZone {
                id: "rural-west".into(),
                kind: "rural".into(),
                world_x: 0,
                world_z: 0,
                width_m: 128,
                depth_m: 512,
                source: "test".into(),
            },
            LandUseZone {
                id: "urban-west".into(),
                kind: "urban".into(),
                world_x: 128,
                world_z: 0,
                width_m: 256,
                depth_m: 512,
                source: "test".into(),
            },
            LandUseZone {
                id: "rural-east".into(),
                kind: "rural".into(),
                world_x: 384,
                world_z: 0,
                width_m: 128,
                depth_m: 512,
                source: "test".into(),
            },
        ];
        let style = serde_json::json!({
            "frontageProgram": {"version": 1, "requests": [{
                "id": "homes",
                "sceneId": scene_id,
                "purpose": "urban",
                "kind": "residential_home",
                // Larger than the authored stage can satisfy on its own, so the
                // sweep must measure at least one candidate realization.
                "count": 24,
                "widthM": 12,
                "depthM": 10,
                "heightM": 8,
                "stationSpacingM": 24,
                "setbackM": 8,
                "maxCandidateAttempts": 256,
                "parcelInsets": {"frontM": 4, "sideM": 2, "rearM": 4}
            }]},
            "automaticRoadExtensions": {"version": 3, "scenes": [{
                "sceneId": scene_id,
                "maxNewSegments": 2,
                "maxCandidateAttempts": 64,
                "segmentLengthsM": [64, 128],
                "priorityPurposes": ["urban"],
                "reachDistanceM": 32,
                "hierarchy": {"tiers": [
                    {"id": "collector-16", "role": "collector", "widthM": 16, "purposes": ["urban"]},
                    {"id": "local-12", "role": "local", "widthM": 12, "purposes": ["urban"]}
                ]},
                "supply": {"version": 1, "maxCandidateStates": 16, "preflightBudgetMs": 180000, "mode": "append"}
            }]},
        });
        (s, t, w, zones, style, seed)
    }

    /// The old heuristic classification sampled 17 points and called a raster
    /// "production-encoder" whenever they all matched.
    fn legacy_probe_points(scene: &SceneSpec) -> Vec<(i32, i32)> {
        let mut points = vec![];
        for row in 0..4 {
            for col in 0..4 {
                points.push((
                    scene.origin_x + (col * 31 + 5),
                    scene.origin_z + (row * 31 + 7),
                ));
            }
        }
        points.push((
            scene.origin_x + scene.width_m as i32 / 2,
            scene.origin_z + scene.depth_m as i32 / 2,
        ));
        points
    }

    /// The *production* entry must hand the declared context to the final
    /// encoder. Observed from inside the real call path on an authored natural
    /// scene with a non-zero effective seed and a non-zero scene seed offset.
    #[test]
    fn production_v3_entry_uses_the_declared_authored_seed() {
        let (s, t, w, zones, style, seed) = authored_fixture("authored-entry");
        let plan = super::super::road_network::plan_with_style_declared(
            &s,
            &t,
            w,
            Some(&zones),
            None,
            &style,
            NaturalSource::AuthoredSeed {
                seed,
                precise: true,
            },
        )
        .unwrap();
        let observed: Vec<(String, u64, bool, &'static str)> =
            super::super::frontage_supply::OBSERVED_FINAL_CONTEXT
                .lock()
                .unwrap()
                .iter()
                .filter(|entry| entry.0 == s.scene_id)
                .cloned()
                .collect();
        assert!(
            !observed.is_empty(),
            "the entry must realize the trusted baseline through the declared source"
        );
        for entry in &observed {
            assert_eq!(
                (entry.1, entry.2, entry.3),
                (seed, true, "production-encoder"),
                "every baseline/candidate measurement must receive the declared seed: {observed:?}"
            );
        }
        let report = plan.automatic_extensions.as_ref().unwrap();
        assert!(
            !report.incomplete,
            "the phase must publish a complete result"
        );
        println!(
            "C2-EVIDENCE {}",
            serde_json::json!({
                "case": "authored-natural-scene",
                "sceneId": s.scene_id,
                "sceneSeedOffset": s.seed_offset,
                "declaredSeed": seed,
                "declaredPrecise": true,
                "observations": observed.iter().map(|(_, seed, precise, source)| {
                    serde_json::json!({"seed": seed, "precise": precise, "source": source})
                }).collect::<Vec<_>>(),
                "stopReason": report.stop_reason,
                "acceptedSegments": report.accepted_segments,
            })
        );
    }

    /// The candidate call site gets the same declared context as the baseline.
    /// The real authored field cannot put a candidate through the measurement
    /// screen (its relief refuses every road profile, exactly as the frozen W1
    /// world does), so this fixture is an explicitly declared *supplied* raster:
    /// what it proves is that the candidate call site honours the declaration
    /// instead of falling back to the old sample-based classification.
    #[test]
    fn production_v3_entry_hands_the_declared_source_to_candidate_realizations() {
        let (s, t, w, z, p, style) = supply_fixture_with_id("declared-source");
        let mut plan = p.clone();
        append_declared(
            &mut plan,
            &s,
            &t,
            w,
            &z,
            &supply_style(&style, 32),
            NaturalSource::SuppliedRaster,
        )
        .unwrap();
        let observed: Vec<(String, u64, bool, &'static str)> =
            super::super::frontage_supply::OBSERVED_FINAL_CONTEXT
                .lock()
                .unwrap()
                .iter()
                .filter(|entry| entry.0 == s.scene_id)
                .cloned()
                .collect();
        assert!(
            observed.len() >= 2,
            "the entry must realize the baseline and at least one candidate: {observed:?}"
        );
        for entry in &observed {
            assert_eq!(
                (entry.1, entry.2, entry.3),
                (0, false, "supplied-raster-carve"),
                "both call sites must receive the declared source: {observed:?}"
            );
        }
        let report = plan.automatic_extensions.as_ref().unwrap();
        assert!(
            report.accepted_segments > 0,
            "the candidate call site must actually be exercised: {:?}",
            report.rejected_by_reason
        );
        println!(
            "C2-EVIDENCE {}",
            serde_json::json!({
                "case": "declared-supplied-raster-candidate",
                "sceneId": s.scene_id,
                "declaration": "SuppliedRaster",
                "observations": observed.iter().map(|(_, seed, precise, source)| {
                    serde_json::json!({"seed": seed, "precise": precise, "source": source})
                }).collect::<Vec<_>>(),
                "acceptedSegments": report.accepted_segments,
                "stopReason": report.stop_reason,
            })
        );
    }

    /// Acceptance: on the same candidate plan the supply final and the
    /// production encoding path must agree on the whole raster, not on a
    /// tolerance.
    #[test]
    fn supply_final_matches_the_production_encoder_bit_for_bit() {
        let (s, t, w, zones, style, seed) = authored_fixture("authored-hash");
        let plan = super::super::road_network::plan_with_style_declared(
            &s,
            &t,
            w,
            Some(&zones),
            None,
            &style,
            NaturalSource::AuthoredSeed {
                seed,
                precise: true,
            },
        )
        .unwrap();
        let source = NaturalSource::AuthoredSeed {
            seed,
            precise: true,
        };
        let (supply_final, label) =
            super::super::frontage_supply::candidate_final_terrain(
                &s,
                &t,
                w,
                &zones,
                &plan,
                source,
            )
            .unwrap();
        assert_eq!(label, "production-encoder");
        let mut entities = plan.entities();
        entities.extend(plan.site_entities());
        for entity in &mut entities {
            entity.normalize_spatial_semantics();
        }
        let carves = super::super::plan_terrain_carves(&entities);
        let mask = super::super::zoning::ZoningMask::new(&s, &zones).unwrap();
        let reference = super::super::generate_chunk_encoded(
            seed,
            s.origin_x,
            s.origin_z,
            s.width_m,
            s.depth_m,
            w,
            &carves,
            true,
            Some(&mask),
        )
        .0;
        let mut reference_terrain = BakedTerrain::new(&s).unwrap();
        reference_terrain
            .insert_chunk(s.origin_x, s.origin_z, s.width_m, s.depth_m, &reference)
            .unwrap();
        assert_eq!(
            supply_final.content_hash().unwrap(),
            reference_terrain.content_hash().unwrap(),
            "the supply final must be the production encoding of the same plan"
        );
        println!(
            "C2-EVIDENCE {}",
            serde_json::json!({
                "case": "supply-final-equals-production-encoder",
                "sceneId": s.scene_id,
                "declaredSeed": seed,
                "supplyFinalSource": label,
                "supplyFinalHash": supply_final.content_hash().unwrap(),
                "productionEncoderHash": reference_terrain.content_hash().unwrap(),
            })
        );
    }

    /// Missing context is refused, never defaulted to a zero seed or a raster
    /// fallback.
    #[test]
    fn undeclared_natural_source_is_refused_by_the_v3_entry() {
        let (s, t, w, zones, style, _seed) = authored_fixture("authored-refused");
        let error = super::super::road_network::plan_with_style_declared(
            &s,
            &t,
            w,
            Some(&zones),
            None,
            &style,
            NaturalSource::Undeclared,
        )
        .unwrap_err();
        assert!(
            error.0.contains("declared natural source"),
            "{}",
            error.0
        );
        // The legacy wrapper keeps its v1/v2 semantics but may not smuggle a v3
        // style through without a declaration either.
        let mut plan =
            super::super::road_network::plan_with_zones(&s, &t, w, Some(&zones)).unwrap();
        let error = append(&mut plan, &s, &t, w, &zones, &style).unwrap_err();
        assert!(
            error.0.contains("declared natural source"),
            "{}",
            error.0
        );
        println!(
            "C2-EVIDENCE {}",
            serde_json::json!({
                "case": "undeclared-source-refused",
                "sceneId": s.scene_id,
                "declaredEntryRefusal": "version 3 supply requires a declared natural source",
                "legacyWrapperRefusal": error.0,
            })
        );
    }

    /// The source is declared, never inferred: a raster edited at one cell that
    /// the old 17-point probe would still call "production-encoder" must be used
    /// verbatim under a `SuppliedRaster` declaration.
    #[test]
    fn a_supplied_raster_edit_outside_the_old_probes_is_not_overwritten() {
        let (s, t, w, zones, style, seed) = authored_fixture("authored-edit");
        let plan = super::super::road_network::plan_with_style_declared(
            &s,
            &t,
            w,
            Some(&zones),
            None,
            &style,
            NaturalSource::AuthoredSeed {
                seed,
                precise: true,
            },
        )
        .unwrap();
        // Edit one cell that the legacy probe never sampled.
        let edited = (s.origin_x + 3, s.origin_z + 3);
        assert!(!legacy_probe_points(&s).contains(&edited));
        let mut values = Vec::with_capacity((s.width_m * s.depth_m) as usize);
        for z in s.origin_z..s.origin_z + s.depth_m as i32 {
            for x in s.origin_x..s.origin_x + s.width_m as i32 {
                let base = f64::from(t.height(x, z).unwrap());
                values.push(if (x, z) == edited { base + 2.0 } else { base });
            }
        }
        let mut edited_terrain = BakedTerrain::new(&s).unwrap();
        edited_terrain
            .insert_chunk(
                s.origin_x,
                s.origin_z,
                s.width_m,
                s.depth_m,
                &encode_millimetres(s.width_m, s.depth_m, values).unwrap(),
            )
            .unwrap();
        // The legacy heuristic would still classify this raster as the authored
        // field: every one of its 17 samples matches.
        for (x, z) in legacy_probe_points(&s) {
            let analytic =
                (super::super::terrain_height_metres(seed, x, z, w, &[]) * 1000.).round() as i32;
            assert!(
                (edited_terrain.height_millimetres(x, z).unwrap() - analytic).abs() <= 1,
                "the counterexample needs every legacy probe to still match"
            );
        }
        let (supplied_final, label) = super::super::frontage_supply::candidate_final_terrain(
            &s,
            &edited_terrain,
            w,
            &zones,
            &plan,
            NaturalSource::SuppliedRaster,
        )
        .unwrap();
        assert_eq!(label, "supplied-raster-carve");
        let (authored_final, authored_label) =
            super::super::frontage_supply::candidate_final_terrain(
                &s,
                &t,
                w,
                &zones,
                &plan,
                NaturalSource::AuthoredSeed {
                    seed,
                    precise: true,
                },
            )
            .unwrap();
        assert_eq!(authored_label, "production-encoder");
        let mut entities = plan.entities();
        entities.extend(plan.site_entities());
        for entity in &mut entities {
            entity.normalize_spatial_semantics();
        }
        let carves = super::super::plan_terrain_carves(&entities);
        let expected = (super::super::apply_terrain_carves(
            f64::from(edited_terrain.height(edited.0, edited.1).unwrap()),
            edited.0,
            edited.1,
            &carves,
        ) * 1000.)
            .round() as i32;
        assert_eq!(
            supplied_final.height_millimetres(edited.0, edited.1).unwrap(),
            expected,
            "a supplied raster must be consumed exactly as handed over"
        );
        assert_ne!(
            supplied_final.height_millimetres(edited.0, edited.1).unwrap(),
            authored_final.height_millimetres(edited.0, edited.1).unwrap(),
            "the edit must survive instead of being regenerated away"
        );
        println!(
            "C2-EVIDENCE {}",
            serde_json::json!({
                "case": "supplied-raster-edit-survives",
                "sceneId": s.scene_id,
                "editedCell": [edited.0, edited.1],
                "legacyProbePoints": legacy_probe_points(&s).len(),
                "legacyProbesStillMatching": legacy_probe_points(&s).len(),
                "suppliedLabel": label,
                "authoredLabel": authored_label,
                "suppliedMillimetres": supplied_final.height_millimetres(edited.0, edited.1).unwrap(),
                "authoredMillimetres": authored_final.height_millimetres(edited.0, edited.1).unwrap(),
            })
        );
    }

    /// Same terrain as `supply_fixture` but with two urban districts, so the
    /// authored automatic stage selects its 16m collector while a demand-led
    /// candidate is a 12m local road that sorts earlier in placement order.
