    #[test]
    fn supply_states_consider_every_authorized_tier() {
        let (s, t, w, z, p, style) = steal_fixture();
        let v3 = supply_style(&style, 32);
        let program = from_style(&v3).unwrap().unwrap();
        let scene_program = &program.scenes[0];
        let hierarchy = scene_program.hierarchy.as_ref().unwrap();
        let mut base = p.clone();
        append(&mut base, &s, &t, w, &z, &style).unwrap();
        let session = SupplySession::for_scene(&v3, "steal", &base).unwrap();
        let states = supply_states(
            &base,
            &s,
            scene_program,
            hierarchy,
            &session,
            &BTreeSet::new(),
        )
        .unwrap();
        let roles: BTreeSet<&str> = states.iter().map(|s| s.tier_role.as_str()).collect();
        assert!(roles.contains("collector"), "collector must be a candidate: {roles:?}");
        assert!(roles.contains("local"), "local must be a candidate: {roles:?}");
        assert_eq!(
            states.iter().find(|s| s.tier_role == "collector").unwrap().width_m,
            16
        );
        assert_eq!(
            states.iter().find(|s| s.tier_role == "local").unwrap().width_m,
            12
        );
    }

    #[test]
    fn real_stages_never_trade_existing_identities_for_new_ones() {
        let (s, t, w, z, p, style) = steal_fixture();
        let v3 = supply_style(&style, 32);
        // Baseline: the authored stage alone realizes part of the demand.
        let mut base = p.clone();
        append(&mut base, &s, &t, w, &z, &style).unwrap();
        let base_roads: Vec<u32> = base
            .extensions
            .iter()
            .map(|e| e.design.request.road_width_m)
            .collect();
        assert!(
            base_roads.contains(&16),
            "the authored stage must pick its collector: {base_roads:?}"
        );
        let mut base_frontage = base.clone();
        super::super::frontage::append(&mut base_frontage, &s, &t, w, Some(&z), &style).unwrap();
        let baseline_ids: Vec<String> = base_frontage
            .frontage
            .as_ref()
            .unwrap()
            .outcomes
            .iter()
            .flat_map(|o| o.site_ids.clone())
            .collect();
        assert!(!baseline_ids.is_empty());
        // The demand-led phase may add parcels, but it may never trade those
        // identities away: either every baseline identity survives, or the
        // candidate was rolled back and the ledger says why.
        let mut led = p.clone();
        append_declared(
            &mut led,
            &s,
            &t,
            w,
            &z,
            &v3,
            NaturalSource::SuppliedRaster,
        )
        .unwrap();
        let report = led.automatic_extensions.as_ref().unwrap();
        let mut after = led.clone();
        super::super::frontage::append(&mut after, &s, &t, w, Some(&z), &v3).unwrap();
        let after_ids: Vec<String> = after
            .frontage
            .as_ref()
            .unwrap()
            .outcomes
            .iter()
            .flat_map(|o| o.site_ids.clone())
            .collect();
        for id in &baseline_ids {
            assert!(
                after_ids.contains(id),
                "a committed plan must keep every baseline identity: {id} vanished ({after_ids:?})"
            );
        }
        if report.accepted_segments == 0 {
            assert!(
                report
                    .rejected_by_reason
                    .keys()
                    .any(|reason| reason.contains("realization_")
                        || reason.contains("no_real_parcel_supply")),
                "a phase that commits nothing must say why: {:?}",
                report.rejected_by_reason
            );
        }
    }

    #[test]
    fn resource_clock_expiry_never_publishes_a_success_prefix() {
        use std::cell::Cell;
        struct StepClock {
            ticks: Cell<u64>,
            trip_at: u64,
        }
        impl SupplyClock for StepClock {
            fn millis(&self) -> u64 {
                let now = self.ticks.get();
                self.ticks.set(now + 1);
                if now >= self.trip_at {
                    180_001
                } else {
                    now
                }
            }
        }
        let (s, t, w, z, p, style) = supply_fixture();
        // Demand for four parcels so a real first success is followed by more
        // rounds: the sweep then covers a trip *after* a commit, while the next
        // round is prepared, and during the next realization.
        let mut styled = supply_style(&style, 32);
        styled["frontageProgram"]["requests"][0]["count"] = serde_json::json!(4);
        let program = from_style(&styled).unwrap().unwrap().scenes[0].clone();
        let mut baseline = p.clone();
        append_legacy(&mut baseline, &s, &t, w, &z, &program, 0).unwrap();
        let baseline_json = serde_json::to_value(&baseline).unwrap();
        let mut outcomes = std::collections::BTreeMap::new();
        let mut discarded_after_commit = 0_usize;
        let mut examined_states = 0_usize;
        for trip_at in 0..80_u64 {
            let mut plan = baseline.clone();
            let clock = StepClock {
                ticks: Cell::new(0),
                trip_at,
            };
            match append_supply_aware(
                &mut plan,
                &s,
                &t,
                w,
                &z,
                &styled,
                &program,
                SupplyMode::Append,
                &clock,
                NaturalSource::SuppliedRaster,
            ) {
                Ok(()) => {
                    let report = plan.automatic_extensions.as_ref().unwrap();
                    assert!(
                        !report.incomplete,
                        "a published plan must never be marked incomplete: trip_at={trip_at}"
                    );
                    *outcomes.entry("complete").or_insert(0_usize) += 1;
                }
                Err(error) => {
                    assert!(
                        error.0.contains("supply_phase_wall_clock_aborted"),
                        "trip_at={trip_at}: {}",
                        error.0
                    );
                    let diagnostic = &error.0[error
                        .0
                        .find('{')
                        .expect("structured diagnostic")..];
                    let diagnostic: serde_json::Value =
                        serde_json::from_str(diagnostic).expect("diagnostic json");
                    if diagnostic["acceptedRoadsDiscarded"].as_u64().unwrap_or(0) > 0 {
                        discarded_after_commit += 1;
                    }
                    examined_states =
                        examined_states.max(diagnostic["candidateStatesExamined"].as_u64().unwrap_or(0) as usize);
                    let mut without_report = plan.clone();
                    without_report.automatic_extensions = None;
                    let mut expected: RoadNetworkPlan =
                        serde_json::from_value(baseline_json.clone()).unwrap();
                    expected.automatic_extensions = None;
                    assert_eq!(
                        serde_json::to_value(&without_report).unwrap(),
                        serde_json::to_value(&expected).unwrap(),
                        "a wall-clock stop must roll the append phase back completely (trip_at={trip_at})"
                    );
                    *outcomes.entry("aborted").or_insert(0_usize) += 1;
                }
            }
        }
        assert!(outcomes.get("complete").copied().unwrap_or(0) > 0, "{outcomes:?}");
        assert!(outcomes.get("aborted").copied().unwrap_or(0) > 0, "{outcomes:?}");
        assert!(
            discarded_after_commit > 0,
            "the sweep must include a wall-clock stop after a real success"
        );
        assert!(examined_states > 0, "the sweep must include a mid-work stop");
    }

    #[test]
    fn transaction_guards_reject_regression_identity_yard_and_unrealized_plans() {
        let (s, t, w, z, p, style) = steal_fixture();
        let v2 = style.clone();
        let v3 = supply_style(&style, 32);
        let mut plan = p.clone();
        append(&mut plan, &s, &t, w, &z, &v2).unwrap();
        let mut verified = plan.clone();
        super::super::frontage::append(&mut verified, &s, &t, w, Some(&z), &v2).unwrap();
        // Real, already-realized identities of this fixture.
        let home_ids: Vec<String> = verified
            .roadside_sites
            .iter()
            .filter(|site| {
                site.program
                    .as_ref()
                    .is_some_and(|program| program.request_id == "homes")
            })
            .map(|site| site.id.clone())
            .collect();
        assert!(
            home_ids.len() >= 2,
            "the fixture baseline must realize at least two parcels: {home_ids:?}"
        );
        let mut baseline = empty_realization(&s.scene_id);
        baseline.realized_ids = home_ids.clone();
        baseline.realized_by_request = vec![("homes".into(), home_ids.len()), ("shops".into(), 0)];
        baseline.realized_ids_by_request = vec![("homes".into(), home_ids.clone())];
        baseline.planned = home_ids.len();
        baseline.realized_with_access = home_ids.len();
        baseline.yard_unresolved_by_parcel = home_ids
            .iter()
            .map(|id| (format!("parcel-of-{id}"), 0.))
            .collect();
        baseline.parcel_by_entity = home_ids
            .iter()
            .map(|id| (id.clone(), format!("parcel-of-{id}")))
            .collect();
        let mut session = SupplySession::for_scene(&v3, &s.scene_id, &verified).unwrap();
        session.adopt(&verified, &baseline).unwrap();
        assert_eq!(session.commitments.len(), home_ids.len());
        // (1) The inspector's counterexample shape: one committed parcel is lost
        //     while the same request *gains* a new one (and a shop too). Counts
        //     alone would pass; the rolling identity set must not.
        let extra = format!("{}.extra", home_ids[0]);
        let mut regression = baseline.clone();
        regression.realized_ids = home_ids[1..]
            .iter()
            .cloned()
            .chain(std::iter::once(extra.clone()))
            .collect();
        regression.realized_by_request = vec![("homes".into(), home_ids.len()), ("shops".into(), 1)];
        regression.realized_ids_by_request =
            vec![("homes".into(), regression.realized_ids.clone())];
        regression.planned = home_ids.len();
        regression.realized_with_access = home_ids.len();
        let base_plan = verified.clone();
        assert_eq!(
            commit_decision(&session, &regression, &baseline, &base_plan).unwrap_err(),
            format!("realization_lost_existing_access:{}", home_ids[0])
        );
        // (2) Same totals, different identities.
        let mut swapped = baseline.clone();
        swapped.realized_ids = vec![format!("{}.clone", home_ids[0]), format!("{}.clone", home_ids[1])];
        swapped.realized_ids_by_request =
            vec![("homes".into(), swapped.realized_ids.clone())];
        assert!(commit_decision(&session, &swapped, &baseline, &base_plan).is_err());
        // (3) Planning credit without realization, and a lost yard.
        let mut unrealized = baseline.clone();
        unrealized.planned = home_ids.len() + 2;
        unrealized.realized_with_access = home_ids.len() + 1;
        unrealized.realized_by_request = vec![("homes".into(), home_ids.len() + 1), ("shops".into(), 0)];
        unrealized.realized_ids = home_ids
            .iter()
            .cloned()
            .chain(std::iter::once(extra.clone()))
            .collect();
        unrealized.realized_ids_by_request =
            vec![("homes".into(), unrealized.realized_ids.clone())];
        let error = commit_decision(&session, &unrealized, &baseline, &base_plan).unwrap_err();
        assert!(error.contains("planned_but_not_realized"), "{error}");
        // (4) A new parcel carrying its own yard shortfall must be refused, even
        //     if an old parcel's shortfall were repaired at the same time.
        let mut yard = baseline.clone();
        yard.realized_ids = home_ids
            .iter()
            .cloned()
            .chain(std::iter::once(extra.clone()))
            .collect();
        yard.realized_by_request = vec![("homes".into(), home_ids.len() + 1), ("shops".into(), 0)];
        yard.realized_ids_by_request = vec![("homes".into(), yard.realized_ids.clone())];
        yard.planned = home_ids.len() + 1;
        yard.realized_with_access = home_ids.len() + 1;
        yard.parcel_by_entity.insert(extra.clone(), "parcel-of-new".into());
        yard.yard_unresolved_by_parcel.insert("parcel-of-new".into(), 13.);
        let error = commit_decision(&session, &yard, &baseline, &base_plan).unwrap_err();
        assert!(error.contains("new_parcel_yard_unresolved"), "{error}");
        // (5) A pure addition with a resolved yard passes.
        let mut enlarged = baseline.clone();
        enlarged.realized_by_request = vec![("homes".into(), home_ids.len() + 1), ("shops".into(), 0)];
        enlarged.realized_ids = yard.realized_ids.clone();
        enlarged.realized_ids_by_request =
            vec![("homes".into(), enlarged.realized_ids.clone())];
        enlarged.planned = home_ids.len() + 1;
        enlarged.realized_with_access = home_ids.len() + 1;
        enlarged.parcel_by_entity.insert(extra.clone(), "parcel-of-new".into());
        assert!(commit_decision(&session, &enlarged, &baseline, &base_plan).is_ok());
        // (6) Per-parcel, not per-total: one old parcel is repaired while
        //     another old parcel grows by the same amount, leaving the total
        //     unchanged. The growing parcel must still be refused.
        let protected: Vec<(String, String)> = session
            .protected_owners
            .iter()
            .map(|(entity, parcel)| (entity.clone(), parcel.clone()))
            .collect();
        let mut shifted = baseline.clone();
        shifted.realized_ids = home_ids
            .iter()
            .cloned()
            .chain(std::iter::once(extra.clone()))
            .collect();
        shifted.realized_by_request = vec![("homes".into(), home_ids.len() + 1), ("shops".into(), 0)];
        shifted.realized_ids_by_request =
            vec![("homes".into(), shifted.realized_ids.clone())];
        shifted.planned = home_ids.len() + 1;
        shifted.realized_with_access = home_ids.len() + 1;
        shifted.parcel_by_entity.insert(extra.clone(), "parcel-of-new".into());
        // Baseline carries no old shortfall in this fixture, so the "growing"
        // side of the move has to come from a parcel whose protected allowance
        // is zero.
        let moved = protected[0].1.clone();
        shifted
            .yard_unresolved_by_parcel
            .insert(moved.clone(), 4.0);
        shifted.yard_unresolved_m2 = 4.0;
        let error = commit_decision(&session, &shifted, &baseline, &base_plan).unwrap_err();
        assert!(error.contains("existing_parcel_yard_grew"), "{error}");
        // (7) A protected baseline asset may not silently change owner.
        let mut reowned = baseline.clone();
        reowned.realized_ids = home_ids
            .iter()
            .cloned()
            .chain(std::iter::once(extra.clone()))
            .collect();
        reowned.realized_by_request = vec![("homes".into(), home_ids.len() + 1), ("shops".into(), 0)];
        reowned.realized_ids_by_request =
            vec![("homes".into(), reowned.realized_ids.clone())];
        reowned.planned = home_ids.len() + 1;
        reowned.realized_with_access = home_ids.len() + 1;
        reowned
            .parcel_by_entity
            .insert(protected[0].0.clone(), "parcel-of-other".into());
        reowned.parcel_by_entity.insert(extra.clone(), "parcel-of-new".into());
        let error = commit_decision(&session, &reowned, &baseline, &base_plan).unwrap_err();
        assert!(error.contains("existing_owner_changed"), "{error}");
        // (8) A protected baseline asset may not vanish from the audit map: an
        //     absent entry is not evidence that its shortfall was resolved.
        let mut vanished = baseline.clone();
        vanished.realized_ids = home_ids
            .iter()
            .cloned()
            .chain(std::iter::once(extra.clone()))
            .collect();
        vanished.realized_by_request = vec![("homes".into(), home_ids.len() + 1), ("shops".into(), 0)];
        vanished.realized_ids_by_request =
            vec![("homes".into(), vanished.realized_ids.clone())];
        vanished.planned = home_ids.len() + 1;
        vanished.realized_with_access = home_ids.len() + 1;
        vanished.parcel_by_entity.remove(&protected[0].0);
        vanished.parcel_by_entity.insert(extra.clone(), "parcel-of-new".into());
        let error = commit_decision(&session, &vanished, &baseline, &base_plan).unwrap_err();
        assert!(error.contains("baseline_asset_missing"), "{error}");
        // (9) A landcover audit that never ran leaves an empty per-parcel map,
        //     which must not read as "every yard resolved".
        let mut unaudited = enlarged.clone();
        unaudited.landcover_status = "landcover_verify_rejected:fixture".into();
        let error = commit_decision(&session, &unaudited, &baseline, &base_plan).unwrap_err();
        assert!(error.contains("landcover_audit_unavailable"), "{error}");
        // (10) A parcel committed by an earlier round is protected exactly like
        //      an entering-baseline parcel: record it the way `adopt` would, then
        //      let it grow. The rejection must be the *existing*-parcel one.
        session
            .protected_owners
            .insert(extra.clone(), "parcel-of-new".into());
        session
            .protected_parcels
            .insert("parcel-of-new".into(), 0.);
        assert!(commit_decision(&session, &enlarged, &baseline, &base_plan).is_ok());
        let mut grown = enlarged.clone();
        grown
            .yard_unresolved_by_parcel
            .insert("parcel-of-new".into(), 2.0);
        grown.yard_unresolved_m2 = 2.0;
        let error = commit_decision(&session, &grown, &baseline, &base_plan).unwrap_err();
        assert!(error.contains("existing_parcel_yard_grew"), "{error}");
    }

    /// Request ids that both pass the production parser, where one id is also a
    /// substring of every generated site id: ownership must come from the
    /// structured mapping, not from the id string.
    #[test]
    fn attribution_uses_the_structured_mapping_not_id_strings() {
        let (s, t, w, z, p, style) = steal_fixture();
        let mut two_requests = style.clone();
        let mut second = two_requests["frontageProgram"]["requests"][0].clone();
        second["id"] = serde_json::json!("scene-0");
        second["kind"] = serde_json::json!("storefront");
        two_requests["frontageProgram"]["requests"] = serde_json::json!([
            two_requests["frontageProgram"]["requests"][0].clone(),
            second,
        ]);
        // Both ids are legal for the production parser.
        let program = from_style(&supply_style(&two_requests, 8)).unwrap().unwrap();
        assert_eq!(program.scenes[0].scene_id, "steal");
        let mut plan = p.clone();
        append(&mut plan, &s, &t, w, &z, &style).unwrap();
        let mut verified = plan.clone();
        super::super::frontage::append(&mut verified, &s, &t, w, Some(&z), &style).unwrap();
        let site = verified
            .roadside_sites
            .iter()
            .find(|site| {
                site.program
                    .as_ref()
                    .is_some_and(|program| program.request_id == "homes")
            })
            .expect("a realized homes parcel")
            .clone();
        assert!(
            site.id.contains(".steal."),
            "the generated id contains the scene id: {}",
            site.id
        );
        let mut session = SupplySession::for_scene(&supply_style(&two_requests, 8), "steal", &verified)
            .unwrap();
        // A homes parcel attributed to the other legal request is refused.
        let mut wrong = empty_realization("steal");
        wrong.realized_ids = vec![site.id.clone()];
        wrong.realized_ids_by_request = vec![("scene-0".into(), vec![site.id.clone()])];
        let error = session.adopt(&verified, &wrong).unwrap_err();
        assert!(error.contains("belongs to homes"), "{error}");
        assert_eq!(session.commitments.len(), 0, "a refused adoption changes nothing");
        // The correct attribution lands exactly once, in its own request only.
        let mut right = empty_realization("steal");
        right.realized_ids = vec![site.id.clone()];
        right.realized_ids_by_request = vec![("homes".into(), vec![site.id.clone()])];
        session.adopt(&verified, &right).unwrap();
        let homes = session
            .budgets
            .iter()
            .find(|b| b.request.id == "homes")
            .unwrap();
        let other = session
            .budgets
            .iter()
            .find(|b| b.request.id == "scene-0")
            .unwrap();
        assert_eq!(homes.site_ids, vec![site.id.clone()]);
        assert!(other.site_ids.is_empty());
        // An id listed under two requests is still attributed to its real owner
        // exactly once, never counted twice.
        let mut ambiguous = empty_realization("steal");
        ambiguous.realized_ids = vec![site.id.clone()];
        ambiguous.realized_ids_by_request = vec![
            ("homes".into(), vec![site.id.clone()]),
            ("scene-0".into(), vec![site.id.clone()]),
        ];
        let mut session2 = SupplySession::for_scene(
            &supply_style(&two_requests, 8),
            "steal",
            &verified,
        )
        .unwrap();
        session2.adopt(&verified, &ambiguous).unwrap();
        assert_eq!(session2.commitments.len(), 1);
        assert_eq!(
            session2
                .budgets
                .iter()
                .find(|b| b.request.id == "homes")
                .unwrap()
                .site_ids
                .len(),
            1
        );
    }

    /// Two rounds inside one phase: the second round may not trade the identity
    /// the first round committed for a larger count, and a normal addition
    /// passes.
    #[test]
    fn rolling_commitments_protect_a_first_round_identity() {
        let (s, t, w, z, p, style) = steal_fixture();
        let mut plan = p.clone();
        append(&mut plan, &s, &t, w, &z, &style).unwrap();
        let mut verified = plan.clone();
        super::super::frontage::append(&mut verified, &s, &t, w, Some(&z), &style).unwrap();
        let home_ids: Vec<String> = verified
            .roadside_sites
            .iter()
            .filter(|site| {
                site.program
                    .as_ref()
                    .is_some_and(|program| program.request_id == "homes")
            })
            .map(|site| site.id.clone())
            .collect();
        assert!(home_ids.len() >= 1);
        let extra = format!("{}.extra", home_ids[0]);
        let mut round_one = empty_realization("steal");
        round_one.realized_ids = vec![home_ids[0].clone()];
        round_one.realized_ids_by_request = vec![("homes".into(), vec![home_ids[0].clone()])];
        round_one.realized_by_request = vec![("homes".into(), 1)];
        let mut session =
            SupplySession::for_scene(&supply_style(&style, 8), "steal", &verified).unwrap();
        session.adopt(&verified, &round_one).unwrap();
        // Round two: the first round's identity is gone while the same request
        // gains two new parcels.
        let mut round_two = empty_realization("steal");
        round_two.realized_ids = vec![extra.clone(), format!("{extra}.b")];
        round_two.realized_ids_by_request =
            vec![("homes".into(), round_two.realized_ids.clone())];
        round_two.realized_by_request = vec![("homes".into(), 2)];
        let error = commit_decision(&session, &round_two, &round_one, &verified).unwrap_err();
        assert!(error.contains(&home_ids[0]), "{error}");
        // A normal addition keeps the identity and passes.
        let mut fine = round_two.clone();
        fine.realized_ids = vec![home_ids[0].clone(), extra.clone()];
        fine.realized_ids_by_request = vec![("homes".into(), fine.realized_ids.clone())];
        fine.realized_by_request = vec![("homes".into(), 2)];
        assert!(commit_decision(&session, &fine, &round_one, &verified).is_ok());
    }

    /// A real realization failure (the candidate's own final raster is damaged
    /// under one planned parcel) must be refused by the accepted audits and roll
    /// the whole append phase back, leaving the trusted baseline untouched.
    #[test]
    fn real_stage_realization_failure_rolls_back_atomically() {
        // This fixture has a candidate that really measures supply, so the
        // realization chain is actually entered.
        let (mut s, t, w, z, mut p, mut style) = supply_fixture();
        // Scope the corruption to a scene id no other test uses, so parallel
        // tests can never observe the damaged raster.
        s.scene_id = "supply-corrupt".into();
        p.scene_id = "supply-corrupt".into();
        p.natural_heightfield_hash = t.content_hash().unwrap();
        style["frontageProgram"]["requests"][0]["sceneId"] = serde_json::json!("supply-corrupt");
        style["automaticRoadExtensions"]["scenes"][0]["sceneId"] =
            serde_json::json!("supply-corrupt");
        let mut v3 = supply_style(&style, 32);
        v3["frontageProgram"]["requests"][0]["count"] = serde_json::json!(4);
        let program = from_style(&v3).unwrap().unwrap().scenes[0].clone();
        let mut baseline = p.clone();
        append_legacy(&mut baseline, &s, &t, w, &z, &program, 0).unwrap();
        let baseline_json = serde_json::to_value(&baseline).unwrap();
        let corruption = super::super::frontage_supply::TEST_CORRUPT_SCENE
            .lock()
            .unwrap()
            .replace(s.scene_id.clone());
        assert!(corruption.is_none(), "the corruption switch is test-scoped");
        let clock = WallClock::start();
        let mut plan = baseline.clone();
        let outcome = append_supply_aware(
            &mut plan,
            &s,
            &t,
            w,
            &z,
            &v3,
            &program,
            SupplyMode::Append,
            &clock,
            NaturalSource::SuppliedRaster,
        );
        super::super::frontage_supply::TEST_CORRUPT_SCENE.lock().unwrap().take();
        outcome.unwrap();
        let report = plan.automatic_extensions.as_ref().unwrap();
        assert_eq!(
            report.accepted_segments, 0,
            "a damaged candidate may not be credited: {:?}",
            report.rejected_by_reason
        );
        assert!(
            report
                .rejected_by_reason
                .keys()
                .any(|reason| reason.contains("realization_")),
            "the refusal must come from the realization chain: {:?}",
            report.rejected_by_reason
        );
        let mut without_report = plan.clone();
        without_report.automatic_extensions = None;
        let mut expected: RoadNetworkPlan = serde_json::from_value(baseline_json).unwrap();
        expected.automatic_extensions = None;
        assert_eq!(
            serde_json::to_value(&without_report).unwrap(),
            serde_json::to_value(&expected).unwrap(),
            "the rollback must leave the trusted baseline untouched"
        );
    }

