    /// Test-only joint junction diagnostic over a closed support intersection.
    ///
    /// Both heights are read through the production `RoadProfile::height_at`
    /// projection (which clamps outside the segment instead of skipping), and
    /// every cell of the closed rectangle must yield both values: a missing
    /// value is reported as `diagnostic_incomplete` and never silently dropped.
    /// It decides nothing — the production append has already decided.
    fn joint_support_diagnostic(
        approach: &super::super::road_profile::RoadProfile,
        street: &super::super::road_profile::RoadProfile,
        rect: [i32; 4],
    ) -> serde_json::Value {
        let mut compared = 0_usize;
        let mut mismatched = 0_usize;
        let mut missing = 0_usize;
        let mut mismatch_cells: Vec<[i32; 2]> = vec![];
        let mut samples: Vec<serde_json::Value> = vec![];
        for z in rect[1]..=rect[3] {
            for x in rect[0]..=rect[2] {
                match (
                    approach.height_at(f64::from(x), f64::from(z)),
                    street.height_at(f64::from(x), f64::from(z)),
                ) {
                    (Some(a), Some(s)) => {
                        compared += 1;
                        let amm = (a * 1000.).round() as i64;
                        let smm = (s * 1000.).round() as i64;
                        if (amm - smm).abs() > 0 {
                            mismatched += 1;
                            mismatch_cells.push([x, z]);
                            if samples.len() < 8 {
                                samples.push(serde_json::json!({
                                    "x": x, "z": z, "approachMm": amm, "streetMm": smm
                                }));
                            }
                        }
                    }
                    _ => missing += 1,
                }
            }
        }
        serde_json::json!({
            "overlap": rect,
            "closedIntersectionCells": (rect[2] - rect[0] + 1) as usize * (rect[3] - rect[1] + 1) as usize,
            "comparedCells": compared,
            "mismatchedCells": mismatched,
            "missingValues": missing,
            "diagnostic_incomplete": missing > 0,
            "mismatchCells": mismatch_cells,
            "samples": samples,
            "note": "production height_at on both profiles; the append decision is production's",
        })
    }

    /// Test-only bundle outcome wrapper with an injectable clock.
    ///
    /// Test-only step clock for the deadline tests: it returns its tick counter
    /// and reports over-budget from `trip_at` onwards. No sleeping.
    struct ExpireClock {
        ticks: std::cell::Cell<u64>,
        trip_at: u64,
    }
    impl SupplyClock for ExpireClock {
        fn millis(&self) -> u64 {
            let now = self.ticks.get();
            self.ticks.set(now + 1);
            if now >= self.trip_at {
                180_001
            } else {
                now
            }
        }
    }

    /// It exists so the V5 harness re-checks the wall clock after every long
    /// stage and before anything is published: a late expiry clears any staged
    /// witness, marks the run incomplete and never lets a witness escape with
    /// `incomplete = false`. It decides nothing about engineering.
    struct BundleOutcome {
        witness: Option<serde_json::Value>,
        incomplete: bool,
        expired_at: Option<&'static str>,
    }
    impl BundleOutcome {
        fn new() -> Self {
            Self {
                witness: None,
                incomplete: false,
                expired_at: None,
            }
        }
        /// Returns false when the budget is already spent; the caller must stop
        /// and publish nothing.
        fn check(&mut self, clock: &dyn SupplyClock, budget_ms: u64, stage: &'static str) -> bool {
            if clock.millis() >= budget_ms {
                self.incomplete = true;
                self.expired_at = Some(stage);
                self.witness = None;
                false
            } else {
                true
            }
        }
        fn stage_witness(
            &mut self,
            clock: &dyn SupplyClock,
            budget_ms: u64,
            witness: serde_json::Value,
        ) -> bool {
            if !self.check(clock, budget_ms, "before-staging-witness") {
                return false;
            }
            self.witness = Some(witness);
            true
        }
        /// Final publication gate: the deadline is re-checked one last time.
        fn finish(
            mut self,
            clock: &dyn SupplyClock,
            budget_ms: u64,
        ) -> (Option<serde_json::Value>, bool, Option<&'static str>) {
            if !self.check(clock, budget_ms, "before-output") {
                return (None, true, self.expired_at);
            }
            (self.witness, self.incomplete, self.expired_at)
        }
    }

    /// Test-only: metres to integer millimetres for evidence fields. The G4 run
    /// serialised `height_at` (metres) into `...Mm` fields; every such field must
    /// go through this conversion instead.
    fn height_mm(height_metres: f64) -> i64 {
        (height_metres * 1000.).round() as i64
    }

    /// Test-only: the end platform plus outer padding range of one segment,
    /// derived from the travel direction and the segment's own junctionLengthM.
    /// The platform reaches `junction_length_m` metres back along the travel
    /// direction from the end; the outer padding reaches 4m past the end; the
    /// lateral extent is width/2 + 3.
    fn end_platform_range(
        start: [i32; 2],
        end: [i32; 2],
        width_m: u32,
        junction_length_m: u32,
    ) -> [i32; 4] {
        let horizontal = start[1] == end[1];
        let direction = if horizontal {
            (end[0] - start[0]).signum()
        } else {
            (end[1] - start[1]).signum()
        };
        let junction = junction_length_m as i32;
        let lateral = width_m as i32 / 2 + 3;
        if horizontal {
            let (x0, x1) = if direction > 0 {
                (end[0] - junction, end[0] + 4)
            } else {
                (end[0] - 4, end[0] + junction)
            };
            [x0, end[1] - lateral, x1, end[1] + lateral]
        } else {
            let (z0, z1) = if direction > 0 {
                (end[1] - junction, end[1] + 4)
            } else {
                (end[1] - 4, end[1] + junction)
            };
            [end[0] - lateral, z0, end[0] + lateral, z1]
        }
    }

    /// B01-G5: the evidence `...Mm` fields are integer millimetres.
    #[test]
    fn the_evidence_height_mm_conversion_is_integral() {
        assert_eq!(height_mm(2.92), 2920);
        assert_eq!(height_mm(2.64), 2640);
        assert_eq!(height_mm(2.56), 2560);
        assert_eq!(height_mm(-0.686), -686);
        assert_eq!(height_mm(0.0), 0);
    }

    /// B01-G5: the end platform range follows the travel direction and the
    /// segment's own junctionLengthM (not a fixed 4m on both sides).
    #[test]
    fn the_end_platform_range_follows_travel_direction_and_junction_length() {
        // BC of the fixed V5 geometry travels west from (288,180) to (176,180)
        let nine = end_platform_range([288, 180], [176, 180], 12, 9);
        assert_eq!(nine, [172, 171, 185, 189]);
        let eight = end_platform_range([288, 180], [176, 180], 12, 8);
        assert_eq!(eight, [172, 171, 184, 189]);
        // the same rule with an eastward or northward travel direction
        assert_eq!(
            end_platform_range([176, 180], [288, 180], 12, 9),
            [279, 171, 292, 189]
        );
        assert_eq!(
            end_platform_range([180, 288], [180, 176], 12, 9),
            [171, 172, 189, 185]
        );
    }

    /// B01-G3: the single authorised V5 two-segment bundle experiment.
    ///
    /// Geometry is frozen: A=(288,96) fixed root 8000mm, shared B=(288,180),
    /// C=(176,180), both segments 12m local, shoulder 3m, junction 8m,
    /// maxFill 6000mm, maxRise 80mm/m. At most 12 bundle states are
    /// pre-registered (the shared B plateau), at most 3 candidates reach a full
    /// realization and the baseline is realized at most once, inside a 180s
    /// wall clock. Segment one is staged in a state-local copy only: it earns no
    /// credit and is discarded unless both segments pass and a real increment is
    /// committed by the accepted gate. Nothing is written to the frozen world.
    #[test]
    #[ignore = "B01-G3 V5 bounded bundle experiment: reads the frozen W1 input, writes only the pre-registered table"]
    fn v5_bundle_tries_for_one_real_parcel_increment() {
        use super::super::frontage_supply::{Realization, SupplyContext, SupplySession};
        use super::super::road_alignment::{AlignmentContext, CorridorRequest};
        use super::super::zoning::ZoningMask;
        use super::super::{LandUseProfile, plan_landuse_zones, terrain_height_metres, water_geometry, water_kind};
        use crate::settlement::morphology_compile;

        let started = std::time::Instant::now();
        let clock = WallClock::start();
        let budget_ms: u64 = 180_000;

        // ---- frozen W1 stage: 35-edge roads-only baseline -------------------
        let manifest_path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(
            "../../work/collaboration/ds-b04-c1-r2-b02-w1/w1-collector-local.manifest.json",
        );
        let manifest: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&manifest_path).unwrap()).unwrap();
        let scene = SceneSpec {
            scene_id: manifest["scenes"][0]["sceneId"].as_str().unwrap().into(),
            width_m: manifest["scenes"][0]["widthM"].as_u64().unwrap() as u32,
            depth_m: manifest["scenes"][0]["depthM"].as_u64().unwrap() as u32,
            origin_x: manifest["scenes"][0]["originX"].as_i64().unwrap() as i32,
            origin_z: manifest["scenes"][0]["originZ"].as_i64().unwrap() as i32,
            seed_offset: manifest["scenes"][0]["seedOffset"].as_u64().unwrap_or(0),
        };
        let seed = manifest["world"]["seed"].as_u64().unwrap();
        assert_eq!(seed, 42);
        let authored = manifest["style"].clone();
        let water = water_geometry(water_kind(&authored), &[], &scene, &authored);
        let compiled = morphology_compile::compile(&authored, std::slice::from_ref(&scene))
            .unwrap()
            .unwrap();
        let style = compiled.style;
        let profile = LandUseProfile::from_style(&style).unwrap();
        let zones = plan_landuse_zones(&scene, &profile);
        let values: Vec<f64> = (0..scene.depth_m as i32)
            .flat_map(|z| (0..scene.width_m as i32).map(move |x| (x, z)))
            .map(|(x, z)| terrain_height_metres(seed, x, z, water, &[]))
            .collect();
        let mut terrain = BakedTerrain::new(&scene).unwrap();
        terrain
            .insert_chunk(
                scene.origin_x,
                scene.origin_z,
                scene.width_m,
                scene.depth_m,
                &encode_millimetres(scene.width_m, scene.depth_m, values).unwrap(),
            )
            .unwrap();
        let mut plan =
            super::super::road_network::plan_with_zones(&scene, &terrain, water, Some(&zones))
                .unwrap();
        super::super::road_extensions::append(&mut plan, &scene, &terrain, water, &zones, &style)
            .unwrap();
        append_declared(
            &mut plan,
            &scene,
            &terrain,
            water,
            &zones,
            &style,
            NaturalSource::AuthoredSeed {
                seed,
                precise: true,
            },
        )
        .unwrap();
        assert_eq!(plan.edges.len(), 35, "the frozen 35-edge baseline");
        assert_eq!(plan.nodes.len(), 27);
        let baseline_plan_hash = {
            let mut hasher = blake3::Hasher::new();
            hasher.update(&serde_json::to_vec(&plan).unwrap());
            hasher.finalize().to_hex().to_string()
        };

        let base =
            super::super::road_network::plan_with_zones(&scene, &terrain, water, Some(&zones))
                .unwrap();
        let trusted = super::super::road_parcel_feasibility::trusted_base_contract(
            &base,
            &terrain.content_hash().unwrap(),
        )
        .unwrap();
        let mut verified = plan.clone();
        super::super::frontage::append(&mut verified, &scene, &terrain, water, Some(&zones), &style)
            .unwrap();
        let obligations = verified
            .roadside_sites
            .iter()
            .filter(|site| site.program.is_none())
            .count();
        assert_eq!(obligations, 21, "the 21 entering obligations");
        // the single permitted baseline realization
        let baseline = super::super::frontage_supply::realize_candidate(
            &scene,
            &terrain,
            water,
            &zones,
            &verified,
            NaturalSource::AuthoredSeed {
                seed,
                precise: true,
            },
            &trusted,
            &style,
        )
        .unwrap();
        assert_eq!(baseline.frontage_requested, 24, "the authored demand stays 24");
        assert_eq!(baseline.final_source, "production-encoder");
        let mut session = SupplySession::for_scene(&style, &scene.scene_id, &verified).unwrap();
        session.adopt(&verified, &baseline).unwrap();
        let ctx = AlignmentContext::new(&scene, &terrain, water, &zones).unwrap();
        let mask = ZoningMask::new(&scene, &zones).unwrap();
        let supply = SupplyContext {
            scene: &scene,
            terrain: &terrain,
            mask: &mask,
            water,
            zones: &zones,
            policy: super::super::bounded_cut::CutPolicy::Disabled,
        };
        let node_levels = levels(&verified, &verified.entities()).unwrap();

        // ---- frozen V5 geometry ---------------------------------------------
        let a = [288, 96];
        let b = [288, 180];
        let c = [176, 180];
        let width_m = 12_u32;
        let fixed_root_mm = *node_levels.get(&a).expect("A is a fixed node");
        assert_eq!(fixed_root_mm, 8000, "the frozen fixed root");
        let request_for = |start: [i32; 2], end: [i32; 2], start_level: Option<i32>| CorridorRequest {
            scene_id: scene.scene_id.clone(),
            start,
            end,
            road_width_m: width_m,
            shoulder_width_m: 3,
            max_fill_mm: 6000,
            max_rise_mm_per_m: 80,
            start_level_mm: start_level,
            end_level_mm: None,
            junction_length_m: 8,
        };
        let approach_base = request_for(a, b, Some(fixed_root_mm));
        let approach_min = ctx.infer_end(&approach_base);
        let b_infer = approach_min
            .as_ref()
            .ok()
            .and_then(|r| r.end_level_mm);
        // V5 window rectangles (16x18 parcels at stations 18/42/66/90 both sides)
        let mut window_rects: Vec<[i32; 4]> = vec![];
        for station in [18_i32, 42, 66, 90] {
            let px = b[0] - station;
            for cz in [b[1] - 23, b[1] + 23] {
                // 12x10 building expanded by front4/side2/rear4 -> 16x18 parcel
                window_rects.push([px - 8, cz - 9, px + 8, cz + 9]);
            }
        }
        let window_natural_max = window_rects
            .iter()
            .flat_map(|r| {
                let mut values = vec![];
                for z in r[1]..=r[3] {
                    for x in r[0]..=r[2] {
                        if let Some(h) = terrain.height_millimetres(x, z) {
                            values.push(h);
                        }
                    }
                }
                values
            })
            .max()
            .unwrap();
        let b_cross_natural_max = {
            let mut max = i32::MIN;
            for z in (b[1] - 9)..=(b[1] + 9) {
                for x in (b[0] - 9)..=(b[0] + 9) {
                    if let Some(h) = terrain.height_millimetres(x, z) {
                        max = max.max(h);
                    }
                }
            }
            max
        };

        // ---- pre-registered table (written before any evaluation) -----------
        let table = serde_json::json!({
            "format": "glyphweave.b01-g3-v5.candidate-table",
            "version": 1,
            "geometry": {"A": a, "B": b, "C": c, "widthM": width_m, "shoulderM": 3,
                         "junctionLengthM": 8, "maxFillMm": 6000, "maxRiseMmPerM": 80,
                         "fixedRootMm": fixed_root_mm},
            "caps": {"maxStates": 12, "maxCandidateRealizations": 3,
                     "maxBaselineRealizations": 1, "runtimeSeconds": 180},
            "cDerivationRule": "street request pinned at B (start_level_mm = Some(B), end_level_mm = None) solved by the production AlignmentContext::infer_end; a derivation error is its own recorded refusal and still counts as an attempt",
            "exceptionBranches": ["approach append refused", "street append refused (including sibling support height mismatch)",
                                   "measurement zero gain", "realization refused", "commit refused",
                                   "wall clock exceeded -> incomplete, nothing committed"],
            "states": [
                {"id": "S01", "bMm": b_infer, "provenance": "production AlignmentContext::infer_end on the approach (minimum feasible plateau)"},
                {"id": "S02", "bMm": 1920, "provenance": "G2-R1 disclosed three-band lower bound at B"},
                {"id": "S03", "bMm": 7692, "provenance": "G2-R1 disclosed three-band upper bound at B"},
                {"id": "S04", "bMm": b_cross_natural_max, "provenance": "frozen natural maximum over the B cross-section (fill-only minimum platform)"},
                {"id": "S05", "bMm": window_natural_max, "provenance": "frozen natural maximum over the 8 V5 parcel windows"}
            ]
        });
        let evidence_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../work/collaboration/ds-b01-g3-v5-bundle");
        std::fs::create_dir_all(&evidence_dir).unwrap();
        let table_path = evidence_dir.join("candidate-table.json");
        let table_text = format!("{}\n", serde_json::to_string_pretty(&table).unwrap());
        let table_reused = if table_path.exists() {
            let existing = std::fs::read_to_string(&table_path).unwrap();
            assert_eq!(
                existing, table_text,
                "a pre-registered table already exists with different content; refusing to overwrite"
            );
            true
        } else {
            let mut file = std::fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&table_path)
                .expect("create the pre-registered table exclusively");
            std::io::Write::write_all(&mut file, table_text.as_bytes()).unwrap();
            false
        };
        let table_hash = {
            let mut hasher = blake3::Hasher::new();
            hasher.update(table_text.as_bytes());
            hasher.finalize().to_hex().to_string()
        };

        // ---- evaluate the frozen states -------------------------------------
        let mut rows: Vec<serde_json::Value> = vec![];
        let mut attempts = 0_usize;
        let mut candidate_realizations = 0_usize;
        let mut design_refusals = 0_usize;
        let mut measurement_zero = 0_usize;
        let mut realization_refusals = 0_usize;
        let mut outcome = BundleOutcome::new();
        // the wall clock is re-checked after every long stage and before
        // anything is published; a late expiry clears any staged witness
        let mut stop = !outcome.check(&clock, budget_ms, "after-baseline-realization");
        let states: Vec<(&str, Option<i32>, &str)> = table["states"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| {
                (
                    s["id"].as_str().unwrap(),
                    s["bMm"].as_i64().map(|v| v as i32),
                    s["provenance"].as_str().unwrap(),
                )
            })
            .collect();
        let mut seen_levels: Vec<i32> = vec![];
        for (id, level, provenance) in states {
            if attempts >= 12 {
                break;
            }
            if stop || !outcome.check(&clock, budget_ms, "before-state") {
                stop = true;
                break;
            }
            attempts += 1;
            let mut row = serde_json::json!({
                "state": id, "bMm": level, "bProvenance": provenance,
                "A": a, "B": b, "C": c, "widthM": width_m, "fixedRootMm": fixed_root_mm,
            });
            let Some(level) = level else {
                row["stage"] = serde_json::json!("derivation_refused");
                row["reason"] = serde_json::json!(approach_min
                    .as_ref()
                    .err()
                    .map(|e| e.0.clone())
                    .unwrap_or_else(|| "no inferred end level".into()));
                rows.push(row);
                continue;
            };
            if seen_levels.contains(&level) {
                row["stage"] = serde_json::json!("duplicate_state_skipped");
                rows.push(row);
                continue;
            }
            seen_levels.push(level);
            // state-local copy: segment one is staged here only
            let mut staged = plan.clone();
            let approach_id = format!("generated.road-supply.g3.{id}.approach");
            let street_id = format!("generated.road-supply.g3.{id}.street");
            let mut approach_request = approach_base.clone();
            approach_request.end_level_mm = Some(level);
            if let Err(error) = super::super::road_extensions::append_one(
                &mut staged,
                &ctx,
                &approach_request,
                approach_id.clone(),
            ) {
                design_refusals += 1;
                row["stage"] = serde_json::json!("approach_design_refused");
                row["reason"] = serde_json::json!(error.0);
                rows.push(row);
                continue;
            }
            // C is derived by the production leaf from the pinned shared B
            let street_base = request_for(b, c, Some(level));
            let street_request = match ctx.infer_end(&street_base) {
                Ok(request) => request,
                Err(error) => {
                    design_refusals += 1;
                    row["stage"] = serde_json::json!("c_derivation_refused");
                    row["reason"] = serde_json::json!(error.0);
                    rows.push(row);
                    continue;
                }
            };
            row["cMm"] = serde_json::json!(street_request.end_level_mm);
            row["cProvenance"] = serde_json::json!("production infer_end on the street pinned at B");
            // Production design of the street, used to record the shared-junction
            // cell comparison (the append below makes the actual decision).
            let approach_entity = staged
                .entities()
                .into_iter()
                .find(|e| e.entity_id == approach_id)
                .expect("the staged approach exists");
            if let (Ok(design), Some(approach_profile)) = (
                ctx.design(&street_request),
                approach_entity.grounding.road_profile.as_ref(),
            ) {
                // the closed intersection comes from the two entities' production
                // support geometry; every cell must yield both heights
                let support_rect = |rotation_y_deg: f32,
                                    width_m: f32,
                                    depth_m: f32,
                                    world_x: i32,
                                    world_z: i32|
                 -> [i64; 4] {
                    let (hw, hd) = if rotation_y_deg == 0. {
                        (width_m as i64 / 2 + 4, depth_m as i64 / 2 + 3)
                    } else {
                        (depth_m as i64 / 2 + 3, width_m as i64 / 2 + 4)
                    };
                    [
                        i64::from(world_x) - hw,
                        i64::from(world_z) - hd,
                        i64::from(world_x) + hw,
                        i64::from(world_z) + hd,
                    ]
                };
                let horizontal = street_request.start[1] == street_request.end[1];
                let street_len = (street_request.end[0] - street_request.start[0]).abs()
                    + (street_request.end[1] - street_request.start[1]).abs();
                let a_rect = support_rect(
                    approach_entity.rotation_y_deg,
                    approach_entity.width_m,
                    approach_entity.depth_m,
                    approach_entity.world_x,
                    approach_entity.world_z,
                );
                let s_rect = support_rect(
                    if horizontal { 0. } else { 90. },
                    street_len as f32,
                    street_request.road_width_m as f32,
                    (street_request.start[0] + street_request.end[0]) / 2,
                    (street_request.start[1] + street_request.end[1]) / 2,
                );
                let rect = [
                    a_rect[0].max(s_rect[0]) as i32,
                    a_rect[1].max(s_rect[1]) as i32,
                    a_rect[2].min(s_rect[2]) as i32,
                    a_rect[3].min(s_rect[3]) as i32,
                ];
                let street_profile = super::super::road_extensions::profile(&design);
                let mut diagnostic =
                    joint_support_diagnostic(approach_profile, &street_profile, rect);
                diagnostic["junctionRadiusM"] = serde_json::json!(9);
                diagnostic["platformM"] = serde_json::json!(8);
                row["sharedJunction"] = diagnostic;
            }
            if let Err(error) = super::super::road_extensions::append_one(
                &mut staged,
                &ctx,
                &street_request,
                street_id.clone(),
            ) {
                design_refusals += 1;
                row["stage"] = serde_json::json!("street_design_refused");
                row["reason"] = serde_json::json!(error.0);
                rows.push(row);
                continue;
            }
            // existing frontage measurement with the shared demand budgets
            let mut probe = staged.clone();
            probe.roadside_sites.extend(session.occupied());
            let mut trial = session.clone();
            let before = trial.realized_totals();
            let mut first_reason = String::new();
            let mut station_attempts = 0_u32;
            for index in 0..trial.budgets.len() {
                if trial.budgets[index].satisfied() || !trial.budgets[index].budget_left() {
                    continue;
                }
                match probe
                    .entities()
                    .into_iter()
                    .find(|e| e.entity_id == street_id)
                    .map(|road| {
                        supply.measure_road_for_request(
                            &probe,
                            &road,
                            &mut trial.budgets[index],
                            SUPPLY_SAMPLE_CAP,
                        )
                    }) {
                    Some(Ok(measured)) => {
                        station_attempts += measured.trace.attempted;
                        if first_reason.is_empty() {
                            first_reason = measured
                                .trace
                                .rejection_details
                                .first()
                                .map(|d| d.reason.clone())
                                .unwrap_or_else(|| "no_station".into());
                        }
                    }
                    Some(Err(error)) => {
                        first_reason = format!("measurement_error:{}", error.0);
                    }
                    None => first_reason = "street_entity_missing".into(),
                }
            }
            let gains: Vec<usize> = trial
                .realized_totals()
                .iter()
                .zip(&before)
                .map(|((_, after), (_, prior))| after.saturating_sub(*prior))
                .collect();
            let total: usize = gains.iter().sum();
            row["measure"] = serde_json::json!({
                "predictedGains": gains, "predictedTotal": total,
                "stationAttempts": station_attempts, "firstReason": first_reason,
            });
            // long design/measure stages have returned: re-check the deadline
            if !outcome.check(&clock, budget_ms, "after-design-and-measure") {
                stop = true;
                row["stage"] = serde_json::json!("late_deadline_after_design_and_measure");
                rows.push(row);
                break;
            }
            if total == 0 {
                measurement_zero += 1;
                row["stage"] = serde_json::json!("measurement_zero_gain");
                rows.push(row);
                continue;
            }
            if candidate_realizations >= 3 {
                row["stage"] = serde_json::json!("realization_budget_exhausted");
                rows.push(row);
                continue;
            }
            candidate_realizations += 1;
            let mut verification = staged.clone();
            let realize_result = (|| -> Result<Realization, String> {
                super::super::frontage::append(
                    &mut verification,
                    &scene,
                    &terrain,
                    water,
                    Some(&zones),
                    &style,
                )
                .map_err(|e| e.0)?;
                super::super::frontage_supply::realize_candidate(
                    &scene,
                    &terrain,
                    water,
                    &zones,
                    &verification,
                    NaturalSource::AuthoredSeed {
                        seed,
                        precise: true,
                    },
                    &trusted,
                    &style,
                )
            })();
            match realize_result {
                Err(reason) => {
                    realization_refusals += 1;
                    row["stage"] = serde_json::json!("realize_refused");
                    row["reason"] = serde_json::json!(reason);
                }
                Ok(realization) => {
                    let decision = commit_decision(&session, &realization, &baseline, &verification);
                    let new_parcels: Vec<String> = realization
                        .parcel_by_entity
                        .iter()
                        .filter(|(entity, _)| !baseline.parcel_by_entity.contains_key(*entity))
                        .map(|(entity, parcel)| format!("{entity} -> {parcel}"))
                        .collect();
                    row["stage"] = serde_json::json!("realized");
                    row["realization"] = serde_json::json!({
                        "finalSource": realization.final_source,
                        "realizedWithAccess": realization.realized_with_access,
                        "realizedByRequest": realization.realized_by_request,
                        "realizedIds": realization.realized_ids,
                        "newParcels": new_parcels,
                        "yardUnresolvedM2": realization.yard_unresolved_m2,
                        "yardUnresolvedByParcel": realization.yard_unresolved_by_parcel,
                        "roadStatus": realization.road_status,
                        "roadFailures": realization.road_failures,
                        "nodeStatus": realization.node_status,
                        "requiredUnconnected": realization.required_unconnected,
                    });
                    row["commit"] = match &decision {
                        Ok(()) => serde_json::json!("accepted"),
                        Err(error) => serde_json::json!(format!("refused:{error}")),
                    };
                    // the realize call has returned: re-check before staging anything
                    if decision.is_ok()
                        && outcome.witness.is_none()
                        && outcome.check(&clock, budget_ms, "after-realize")
                    {
                        let staged_witness = serde_json::json!({
                            "state": id,
                            "bMm": level,
                            "bProvenance": provenance,
                            "cMm": street_request.end_level_mm,
                            "approachId": approach_id,
                            "streetId": street_id,
                            "baselineEdges": 35,
                            "candidateEdges": verification.edges.len(),
                            "baselineObligations": obligations,
                            "baselineRequested": baseline.frontage_requested,
                            "baselineRealizedWithAccess": baseline.realized_with_access,
                            "realizedWithAccess": realization.realized_with_access,
                            "realizedByRequest": realization.realized_by_request,
                            "realizedIds": realization.realized_ids,
                            "newParcels": new_parcels,
                            "yardUnresolvedM2": realization.yard_unresolved_m2,
                            "baselineYardUnresolvedByParcel": baseline.yard_unresolved_by_parcel,
                            "finalSource": realization.final_source,
                            "roadStatus": realization.road_status,
                            "nodeStatus": realization.node_status,
                            "requiredUnconnected": realization.required_unconnected,
                            "baselineIdentitiesKept": baseline
                                .realized_ids
                                .iter()
                                .all(|id| realization.realized_ids.contains(id)),
                        });
                        if !outcome.stage_witness(&clock, budget_ms, staged_witness) {
                            stop = true;
                            rows.push(row);
                            break;
                        }
                    }
                }
            }
            rows.push(row);
            if outcome.witness.is_some() {
                break;
            }
        }
        // final publication gate: the deadline is re-checked one last time, so a
        // late expiry can never let a witness escape with incomplete = false
        let (published_best, published_incomplete, expired_at) =
            outcome.finish(&clock, budget_ms);
        let baseline_plan_hash_after = {
            let mut hasher = blake3::Hasher::new();
            hasher.update(&serde_json::to_vec(&plan).unwrap());
            hasher.finalize().to_hex().to_string()
        };
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "format": "glyphweave.b01-g3-v5.bundle-run",
                "version": 1,
                "tableHash": table_hash,
                "tablePreExisting": table_reused,
                "frozen": {
                    "manifest": "bevy/work/collaboration/ds-b04-c1-r2-b02-w1/w1-collector-local.manifest.json",
                    "seed": seed, "declaredSource": "AuthoredSeed", "precise": true,
                    "baselineEdges": 35, "baselineNodes": 27, "baselineObligations": obligations,
                    "fixedRootMm": fixed_root_mm,
                },
                "baselinePlanHashBefore": baseline_plan_hash,
                "baselinePlanHashAfter": baseline_plan_hash_after,
                "baselineRealizations": 1,
                "baseline": {
                    "requested": baseline.frontage_requested,
                    "realizedWithAccess": baseline.realized_with_access,
                    "yardUnresolvedM2": baseline.yard_unresolved_m2,
                    "yardUnresolvedByParcel": baseline.yard_unresolved_by_parcel,
                    "finalSource": baseline.final_source,
                },
                "attemptedStates": attempts,
                "candidateRealizations": candidate_realizations,
                "counts": {
                    "designRefusals": design_refusals,
                    "measurementZeroGain": measurement_zero,
                    "realizationRefusals": realization_refusals,
                },
                "incomplete": published_incomplete,
                "expiredAt": expired_at,
                "seconds": started.elapsed().as_secs_f64(),
                "bestLegalCandidate": published_best,
                "stopRequested": stop,
                "rows": rows,
            }))
            .unwrap()
        );
    }

    /// B01-G6-R1: the corrected bounded diagnostic replay of the two G5 states.
    ///
    /// No parameter change, no new elevation, no fill relaxation, no new state.
    /// It replays the same two registered states (BC pinned at the G5-recorded C
    /// values) and keeps the production `measure_road_for_request` traces from
    /// all four calls verbatim (`sample_cap = 8`, so every attempt survives).
    ///
    /// Two things the first diagnosis got wrong and this entry fixes:
    /// * every attempt is bound to the real candidate building through the
    ///   production `frontage::candidate_site`, so footprint/yaw/support range
    ///   describe the 12x10 building instead of the 112x12 BC road;
    /// * the first violating point's deficit and the full support rectangle's
    ///   maximum deficit are separate fields, so a first-point reading can never
    ///   be quoted as the lift a state would need.
    ///
    /// Raw production `samples`/`rejection_details` are persisted whole (including
    /// `conflicting_entity`/`before_mm`/`after_mm`) and the complete AB/BC
    /// profiles are stored per state. Completeness is reported as five separate
    /// flags; a single `detailComplete` flag is never used as proof.
    #[test]
    #[ignore = "B01-G6-R1 corrected frontage rejection diagnosis: reads the frozen W1 input, writes only the pre-registered rule table"]
    fn v5_frontage_rejection_diagnosis_r1() {
        use super::super::road_alignment::{AlignmentContext, CorridorRequest};
        use super::super::zoning::ZoningMask;
        use super::super::{
            LandUseProfile, plan_landuse_zones, terrain_height_metres, water_geometry, water_kind,
        };
        use crate::settlement::morphology_compile;

        let started = std::time::Instant::now();
        let clock = WallClock::start();
        let budget_ms: u64 = 120_000;
        let mut outcome = BundleOutcome::new();
        let sample_cap = 8_usize;

        // ---- frozen W1 stage (one rebuild, roads-only baseline) -------------
        let manifest_path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(
            "../../work/collaboration/ds-b04-c1-r2-b02-w1/w1-collector-local.manifest.json",
        );
        let manifest: serde_json::Value =
            serde_json::from_slice(&std::fs::read(&manifest_path).unwrap()).unwrap();
        let scene = SceneSpec {
            scene_id: manifest["scenes"][0]["sceneId"].as_str().unwrap().into(),
            width_m: manifest["scenes"][0]["widthM"].as_u64().unwrap() as u32,
            depth_m: manifest["scenes"][0]["depthM"].as_u64().unwrap() as u32,
            origin_x: manifest["scenes"][0]["originX"].as_i64().unwrap() as i32,
            origin_z: manifest["scenes"][0]["originZ"].as_i64().unwrap() as i32,
            seed_offset: manifest["scenes"][0]["seedOffset"].as_u64().unwrap_or(0),
        };
        let world_seed = manifest["world"]["seed"].as_u64().unwrap();
        let authored = manifest["style"].clone();
        let water = water_geometry(water_kind(&authored), &[], &scene, &authored);
        let compiled = morphology_compile::compile(&authored, std::slice::from_ref(&scene))
            .unwrap()
            .unwrap();
        let style = compiled.style;
        let profile = LandUseProfile::from_style(&style).unwrap();
        let zones = plan_landuse_zones(&scene, &profile);
        let values: Vec<f64> = (0..scene.depth_m as i32)
            .flat_map(|z| (0..scene.width_m as i32).map(move |x| (x, z)))
            .map(|(x, z)| terrain_height_metres(world_seed, x, z, water, &[]))
            .collect();
        let mut terrain = BakedTerrain::new(&scene).unwrap();
        terrain
            .insert_chunk(
                scene.origin_x,
                scene.origin_z,
                scene.width_m,
                scene.depth_m,
                &encode_millimetres(scene.width_m, scene.depth_m, values).unwrap(),
            )
            .unwrap();
        let mut plan =
            super::super::road_network::plan_with_zones(&scene, &terrain, water, Some(&zones))
                .unwrap();
        super::super::road_extensions::append(&mut plan, &scene, &terrain, water, &zones, &style)
            .unwrap();
        append_declared(
            &mut plan,
            &scene,
            &terrain,
            water,
            &zones,
            &style,
            NaturalSource::AuthoredSeed {
                seed: world_seed,
                precise: true,
            },
        )
        .unwrap();
        assert_eq!(plan.edges.len(), 35, "the frozen 35-edge baseline");
        assert_eq!(plan.nodes.len(), 27);
        let baseline_plan_hash = {
            let mut hasher = blake3::Hasher::new();
            hasher.update(&serde_json::to_vec(&plan).unwrap());
            hasher.finalize().to_hex().to_string()
        };
        let mut verified = plan.clone();
        super::super::frontage::append(&mut verified, &scene, &terrain, water, Some(&zones), &style)
            .unwrap();
        assert_eq!(
            verified
                .roadside_sites
                .iter()
                .filter(|s| s.program.is_none())
                .count(),
            21
        );
        let ctx = AlignmentContext::new(&scene, &terrain, water, &zones).unwrap();
        let mask = ZoningMask::new(&scene, &zones).unwrap();
        let supply = super::super::frontage_supply::SupplyContext {
            scene: &scene,
            terrain: &terrain,
            mask: &mask,
            water,
            zones: &zones,
            policy: super::super::bounded_cut::CutPolicy::Disabled,
        };
        let node_levels = levels(&verified, &verified.entities()).unwrap();

        let a = [288, 96];
        let b = [288, 180];
        let c = [176, 180];
        let width_m = 12_u32;
        let junction_length_m = 9_u32;
        let fixed_root_mm = *node_levels.get(&a).expect("A is a fixed node");
        let b_level = 3000_i32;
        let request_for = |start: [i32; 2],
                           end: [i32; 2],
                           start_level: Option<i32>,
                           end_level: Option<i32>| CorridorRequest {
            scene_id: scene.scene_id.clone(),
            start,
            end,
            road_width_m: width_m,
            shoulder_width_m: 3,
            max_fill_mm: 6000,
            max_rise_mm_per_m: 80,
            start_level_mm: start_level,
            end_level_mm: end_level,
            junction_length_m,
        };
        let roadbed_fill_cap_mm = (plan.max_roadbed_fill_m * 1000.).round() as i64;

        // one cross-check of the G5-recorded R1 minimum; the registered values
        // stay the state source and no second state is created from this
        let cross_checked_minimum = ctx
            .infer_end(&request_for(b, c, Some(b_level), None))
            .ok()
            .and_then(|r| r.end_level_mm);
        let states: Vec<(&str, i32, &str)> = vec![
            (
                "J9-R1",
                -382,
                "G5-recorded C from production infer_end under junctionLength=9",
            ),
            ("J9-R2", b_level, "G5-recorded chosenC = B = 3000mm"),
        ];

        let table = serde_json::json!({
            "format": "glyphweave.b01-g6-r1-diagnostic-repair.rules",
            "version": 1,
            "geometry": {"A": a, "B": b, "C": c, "widthM": width_m, "fixedRootMm": fixed_root_mm,
                         "bLevelMm": b_level, "shoulderM": 3, "junctionLengthM": junction_length_m,
                         "maxFillMm": 6000, "maxRiseMmPerM": 80},
            "sampleCap": sample_cap,
            "caps": {"candidateStates": 2, "measureCalls": 4, "stationAttempts": 32, "runtimeSeconds": 120},
            "states": states.iter().map(|(id, level, why)| serde_json::json!({"id": id, "cMm": level, "provenance": why})).collect::<Vec<_>>(),
            "repairs": {
                "candidateBinding": "sample_entity_for (which returned the BC road) is deleted; every attempt is bound with frontier::candidate_site and no road fallback",
                "deficits": "first violating point deficit and full support rectangle maximum deficit are separate fields",
                "rawFields": "raw samples and rejection_details are persisted whole, including conflicting_entity/before_mm/after_mm",
                "profiles": "complete AB/BC CorridorDesign and profile_mm arrays are stored per state",
            },
            "h1Status": "not executed and not approved: the 696mm first-point reading is retracted as a sufficiency claim",
            "purpose": "corrected replay only: keep every production measure trace, bind the real candidate building, and separate first-point from full-support deficits; no parameter change, no new elevation, no fill relaxation"
        });
        let evidence_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../work/collaboration/ds-b01-g6-r1-diagnostic-repair");
        std::fs::create_dir_all(&evidence_dir).unwrap();
        let table_path = evidence_dir.join("rule-table.json");
        let table_text = format!("{}\n", serde_json::to_string_pretty(&table).unwrap());
        let table_reused = if table_path.exists() {
            let existing = std::fs::read_to_string(&table_path).unwrap();
            assert_eq!(existing, table_text, "a pre-registered rule table already exists with different content; refusing to overwrite");
            true
        } else {
            let mut file = std::fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&table_path)
                .expect("create the pre-registered rule table exclusively");
            std::io::Write::write_all(&mut file, table_text.as_bytes()).unwrap();
            false
        };
        let table_hash = {
            let mut hasher = blake3::Hasher::new();
            hasher.update(table_text.as_bytes());
            hasher.finalize().to_hex().to_string()
        };

        let mut rows: Vec<serde_json::Value> = vec![];
        let mut per_request: Vec<serde_json::Value> = vec![];
        let mut raw_traces: Vec<serde_json::Value> = vec![];
        let mut profiles: Vec<serde_json::Value> = vec![];
        let mut trace_count_complete = true;
        let mut sample_binding_valid = true;
        let mut geometry_valid = true;
        let mut raw_detail_persisted = true;
        let mut profile_persisted = true;
        let mut counts = serde_json::json!({
            "preparationStage": {
                "frozenStageRebuilds": 1, "frontageVerificationAppends": 1,
                "alignmentContextNews": 1, "zoningMaskNews": 1,
            },
            "candidateStage": {
                "inferEndCrossChecks": 1, "designCalls": 0, "appendCalls": 0, "measureCalls": 0,
                "candidateRealizeCalls": 0, "baselineRealizeCalls": 0,
                "candidateFinalTerrainCalls": 0, "bakes": 0,
            },
            "internalCalls": "not_instrumented",
        });
        let mut stop = !outcome.check(&clock, budget_ms, "after-stage-rebuild");
        for (state, c_level, provenance) in states {
            if stop {
                break;
            }
            if !outcome.check(&clock, budget_ms, "before-state") {
                stop = true;
                break;
            }
            let mut staged = plan.clone();
            let ab_id = format!("generated.road-supply.g6.{state}.ab");
            let bc_id = format!("generated.road-supply.g6.{state}.bc");
            let ab_request = request_for(a, b, Some(fixed_root_mm), Some(b_level));
            counts["candidateStage"]["designCalls"] =
                serde_json::json!(counts["candidateStage"]["designCalls"].as_u64().unwrap() + 1);
            let ab_design = ctx.design(&ab_request).expect("AB design");
            counts["candidateStage"]["appendCalls"] =
                serde_json::json!(counts["candidateStage"]["appendCalls"].as_u64().unwrap() + 1);
            super::super::road_extensions::append_one(&mut staged, &ctx, &ab_request, ab_id.clone())
                .unwrap_or_else(|e| panic!("G5 AB append must still pass for {state}: {}", e.0));
            let bc_request = request_for(b, c, Some(b_level), Some(c_level));
            counts["candidateStage"]["designCalls"] =
                serde_json::json!(counts["candidateStage"]["designCalls"].as_u64().unwrap() + 1);
            let bc_design = ctx.design(&bc_request).expect("BC design");
            counts["candidateStage"]["appendCalls"] =
                serde_json::json!(counts["candidateStage"]["appendCalls"].as_u64().unwrap() + 1);
            super::super::road_extensions::append_one(&mut staged, &ctx, &bc_request, bc_id.clone())
                .unwrap_or_else(|e| panic!("G5 BC append must still pass for {state}: {}", e.0));
            // The persisted profiles are the staged roads' own arrays, so they are
            // the same objects production would carry, never a re-derived summary.
            let staged_ab = staged
                .entities()
                .into_iter()
                .find(|e| e.entity_id == ab_id)
                .expect("the staged AB road");
            let staged_bc = staged
                .entities()
                .into_iter()
                .find(|e| e.entity_id == bc_id)
                .expect("the staged BC road");
            let ab_profile_mm = staged_ab
                .grounding
                .road_profile
                .as_ref()
                .expect("staged AB profile")
                .elevations_mm
                .clone();
            let bc_profile_mm = staged_bc
                .grounding
                .road_profile
                .as_ref()
                .expect("staged BC profile")
                .elevations_mm
                .clone();
            assert_eq!(
                ab_profile_mm, ab_design.profile_mm,
                "the AB plan profile is the design profile"
            );
            assert_eq!(
                bc_profile_mm, bc_design.profile_mm,
                "the BC plan profile is the design profile"
            );
            // the stored arrays are the whole profiles of their own requests
            let expected_profile_len = |request: &CorridorRequest| -> usize {
                (i64::from(request.end[0]) - i64::from(request.start[0])).abs() as usize
                    + (i64::from(request.end[1]) - i64::from(request.start[1])).abs() as usize
                    + 1
            };
            let ab_expected_len = expected_profile_len(&ab_request);
            let bc_expected_len = expected_profile_len(&bc_request);
            assert_eq!(
                ab_profile_mm.len(),
                ab_expected_len,
                "the whole AB profile is stored, not a summary"
            );
            assert_eq!(
                bc_profile_mm.len(),
                bc_expected_len,
                "the whole 112m BC profile is stored, not length plus endpoints"
            );
            assert_eq!(bc_expected_len, 113);
            let ab_profile_hash = hash_json(&ab_profile_mm);
            let bc_profile_hash = hash_json(&bc_profile_mm);
            profile_persisted &= ab_profile_mm.len() == ab_expected_len
                && bc_profile_mm.len() == bc_expected_len;
            profiles.push(serde_json::json!({
                "state": state,
                "provenance": provenance,
                "protocol": "full production CorridorDesign plus the staged road's own profile_mm",
                "abRequest": ab_request,
                "bcRequest": bc_request,
                "abDesign": ab_design,
                "bcDesign": bc_design,
                "abProfileMm": ab_profile_mm,
                "bcProfileMm": bc_profile_mm,
                "abProfileHashBlake3": ab_profile_hash,
                "bcProfileHashBlake3": bc_profile_hash,
                "stagedRoadCount": staged.entities().len(),
                "baselinePlanHashBlake3": baseline_plan_hash,
            }));
            // production measurement per request, keeping every attempt
            let mut probe = staged.clone();
            probe.roadside_sites.extend(session_occupied_placeholder());
            let mut trial = super::super::frontage_supply::SupplySession::for_scene(
                &style,
                &scene.scene_id,
                &verified,
            )
            .unwrap();
            let before = trial.realized_totals();
            for index in 0..trial.budgets.len() {
                if trial.budgets[index].satisfied() || !trial.budgets[index].budget_left() {
                    continue;
                }
                let request_id = trial.budgets[index].request.id.clone();
                let request_kind = trial.budgets[index].request.kind.clone();
                // the exact production request the shared budget drives the
                // measurement with; the candidate site must be rebuilt from it
                let request = trial.budgets[index].request.clone();
                let Some(road) = probe.entities().into_iter().find(|e| e.entity_id == bc_id)
                else {
                    break;
                };
                let (road_w, road_d) = super::super::spatial_half_extents(
                    road.width_m,
                    road.depth_m,
                    road.rotation_y_deg,
                );
                let road_bounds = [
                    i64::from(road.world_x) - road_w as i64 - 2,
                    i64::from(road.world_z) - road_d as i64 - 2,
                    i64::from(road.world_x) + road_w as i64 + 2,
                    i64::from(road.world_z) + road_d as i64 + 2,
                ];
                counts["candidateStage"]["measureCalls"] = serde_json::json!(
                    counts["candidateStage"]["measureCalls"].as_u64().unwrap() + 1
                );
                let measured = supply
                    .measure_road_for_request(
                        &probe,
                        &road,
                        &mut trial.budgets[index],
                        sample_cap,
                    )
                    .unwrap();
                let trace = &measured.trace;
                let rejected_total: u32 = trace.rejected.values().sum();
                let counts_match = trace.samples.len() == trace.attempted as usize
                    && trace.rejection_details.len() == rejected_total as usize
                    && trace.accepted == trace.accepted_ids.len();
                trace_count_complete &= counts_match;
                raw_detail_persisted &= trace.rejection_details.len() == rejected_total as usize;
                raw_traces.push(json_map(vec![
                    ("state", serde_json::json!(state)),
                    ("requestId", serde_json::json!(request_id)),
                    ("requestKind", serde_json::json!(request_kind)),
                    ("roadId", serde_json::json!(bc_id)),
                    ("request", serde_json::json!(request)),
                    ("roadEntityId", serde_json::json!(road.entity_id)),
                    ("roadEntityKind", serde_json::json!(road.kind)),
                    ("roadWidthM", serde_json::json!(trace.road_width_m)),
                    ("profileLengthM", serde_json::json!(trace.profile_length_m)),
                    ("marginM", serde_json::json!(trace.margin_m)),
                    ("stationStart", serde_json::json!(trace.station_start)),
                    ("stationCount", serde_json::json!(trace.station_count)),
                    ("attemptsBudget", serde_json::json!(trace.attempts_budget)),
                    ("attempted", serde_json::json!(trace.attempted)),
                    ("accepted", serde_json::json!(trace.accepted)),
                    ("acceptedIds", serde_json::json!(trace.accepted_ids)),
                    ("geometryExhausted", serde_json::json!(trace.geometry_exhausted)),
                    ("samplesStored", serde_json::json!(trace.samples.len())),
                    (
                        "rejectionDetailsStored",
                        serde_json::json!(trace.rejection_details.len()),
                    ),
                    ("countsMatch", serde_json::json!(counts_match)),
                    ("roadSupportRangeAt2m", serde_json::json!(road_bounds)),
                    (
                        "protocol",
                        serde_json::json!("verbatim production frontage_supply::RoadSupply"),
                    ),
                    ("trace", serde_json::to_value(trace).unwrap()),
                ]));
                // Pair every rejected sample with the next structured detail in
                // attempt order (never by index across differing arrays) and bind
                // each one to the real production candidate building.
                let mut detail_iter = trace.rejection_details.iter();
                let mut request_binding_ok = true;
                let mut request_scan_ok = true;
                let mut request_geometry_ok = true;
                let mut request_raw_detail_ok = true;
                let mut request_rows = 0_usize;
                for sample in &trace.samples {
                    let detail = if sample.outcome == "accepted" {
                        None
                    } else {
                        detail_iter.next()
                    };
                    if sample.outcome != "accepted" && detail.is_none() {
                        request_raw_detail_ok = false;
                    }
                    let (at, natural_mm, design_mm, note, raw_detail) = match detail {
                        Some(d) => (
                            d.at,
                            d.natural_mm,
                            d.design_mm,
                            d.note.clone().unwrap_or_else(|| d.reason.clone()),
                            serde_json::to_value(d).ok(),
                        ),
                        None if sample.outcome != "accepted" => {
                            (None, None, None, "detail_missing".to_string(), None)
                        }
                        None => (None, None, None, "accepted".to_string(), None),
                    };
                    let required_fill_mm = match (design_mm, natural_mm) {
                        (Some(d), Some(n)) => Some(i64::from(d) - i64::from(n)),
                        _ => None,
                    };
                    let zone_cap_mm = at.map(|p| (mask.fill_capacity_at(p[0], p[1]) * 1000.) as i64);
                    let production_first_point_deficit_mm = match (design_mm, natural_mm) {
                        (Some(d), Some(n)) if i64::from(n) > i64::from(d) => {
                            Some(i64::from(n) - i64::from(d))
                        }
                        _ => None,
                    };
                    let bound = bind_candidate_site(&road, &request, &scene.scene_id, sample);
                    let binding_error = bound.as_ref().err().cloned();
                    let geometry = bound.as_ref().ok().map(|b| {
                        // R7-1.4: a missing precise support must never read as 0 mm; fall
                        // back to the site's integer-metre support (the legacy sites).
                        let level = i64::from(
                            b.site
                                .support_level_mm
                                .unwrap_or_else(|| b.site.support_level_m * 1000),
                        );
                        let scan = scan_support_rectangle(
                            &terrain,
                            &mask,
                            b.support_range,
                            level,
                            roadbed_fill_cap_mm,
                        );
                        let agrees = match (at, scan.first_no_cut_at) {
                            (Some(a), Some(first)) => a == first,
                            (None, None) => true,
                            _ => false,
                        };
                        (scan, agrees)
                    });
                    let scan_agrees = geometry.as_ref().map_or(false, |(_, agrees)| *agrees);
                    let geometry_ok = bound.is_ok()
                        && geometry.as_ref().map_or(false, |(scan, _)| scan.samples > 0)
                        && bound
                            .as_ref()
                            .map_or(false, |b| b.support_range != road_bounds)
                        && bound.as_ref().map_or(false, |b| {
                            (b.site.width_m, b.site.depth_m) == (request.width_m, request.depth_m)
                        })
                        && (note != "natural_above_design_level" || scan_agrees);
                    if bound.is_err() {
                        request_binding_ok = false;
                        request_scan_ok = false;
                    }
                    if !scan_agrees {
                        request_scan_ok = false;
                    }
                    request_geometry_ok &= geometry_ok;
                    request_raw_detail_ok &= sample.outcome == "accepted" || raw_detail.is_some();
                    request_rows += 1;
                    let scan = geometry.as_ref().map(|(scan, _)| scan);
                    rows.push(json_map(vec![
                        ("state", serde_json::json!(state)),
                        ("requestId", serde_json::json!(request_id)),
                        ("requestKind", serde_json::json!(request_kind)),
                        ("roadId", serde_json::json!(bc_id)),
                        ("station", serde_json::json!(sample.station)),
                        ("side", serde_json::json!(sample.side)),
                        ("sampleCentre", serde_json::json!([sample.world_x, sample.world_z])),
                        (
                            "candidateCentre",
                            serde_json::json!(bound
                                .as_ref()
                                .ok()
                                .map(|b| [b.site.world_x, b.site.world_z])),
                        ),
                        (
                            "yaw",
                            serde_json::json!(bound.as_ref().ok().map(|b| b.entity.rotation_y_deg)),
                        ),
                        (
                            "buildingFootprintM",
                            serde_json::json!(bound
                                .as_ref()
                                .ok()
                                .map(|b| [b.entity.width_m, b.entity.depth_m])),
                        ),
                        (
                            "buildingEntityId",
                            serde_json::json!(bound
                                .as_ref()
                                .ok()
                                .map(|b| b.entity.entity_id.clone())),
                        ),
                        (
                            "buildingEntityKind",
                            serde_json::json!(bound.as_ref().ok().map(|b| b.entity.kind.clone())),
                        ),
                        ("roadEntityId", serde_json::json!(road.entity_id)),
                        ("roadEntityKind", serde_json::json!(road.kind)),
                        ("parcel", serde_json::json!(sample.parcel)),
                        ("parcelMatchesSample", serde_json::json!(bound.is_ok())),
                        (
                            "supportCheckRange",
                            serde_json::json!(bound.as_ref().ok().map(|b| b.support_range)),
                        ),
                        ("roadSupportRangeAt2m", serde_json::json!(road_bounds)),
                        (
                            "supportRangeIsNotRoadRange",
                            serde_json::json!(bound
                                .as_ref()
                                .ok()
                                .map(|b| b.support_range != road_bounds)),
                        ),
                        ("bindingValid", serde_json::json!(bound.is_ok())),
                        ("bindingError", serde_json::json!(binding_error)),
                        ("outcome", serde_json::json!(sample.outcome)),
                        ("note", serde_json::json!(note)),
                        ("at", serde_json::json!(at)),
                        ("naturalMm", serde_json::json!(natural_mm)),
                        ("designMm", serde_json::json!(design_mm)),
                        ("requiredFillMm", serde_json::json!(required_fill_mm)),
                        (
                            "productionFirstPointDeficitMm",
                            serde_json::json!(production_first_point_deficit_mm),
                        ),
                        (
                            "supportNoCutFirstPointDeficitMm",
                            serde_json::json!(scan.and_then(|s| s.first_no_cut_deficit_mm)),
                        ),
                        (
                            "supportNoCutMaxDeficitMm",
                            serde_json::json!(scan.and_then(|s| s.max_no_cut_deficit_mm)),
                        ),
                        (
                            "supportNoCutFirstPointAt",
                            serde_json::json!(scan.and_then(|s| s.first_no_cut_at)),
                        ),
                        (
                            "supportNaturalMm",
                            serde_json::json!(scan.map(|s| json_map(vec![
                                ("samples", serde_json::json!(s.samples)),
                                ("minMm", serde_json::json!(s.min_mm)),
                                ("minAt", serde_json::json!(s.min_at)),
                                ("maxMm", serde_json::json!(s.max_mm)),
                                ("maxAt", serde_json::json!(s.max_at)),
                                (
                                    "scope",
                                    serde_json::json!(
                                        "candidate building + 2m production support rectangle (closed, z-then-x)"
                                    ),
                                ),
                            ]))),
                        ),
                        (
                            "supportNecessaryLevelRangeMm",
                            serde_json::json!(scan.map(|s| json_map(vec![
                                ("minMm", serde_json::json!(s.max_mm)),
                                ("maxMm", serde_json::json!(s.fill_upper_mm)),
                                ("maxAt", serde_json::json!(s.fill_upper_at)),
                                (
                                    "scope",
                                    serde_json::json!(
                                        "necessary only: level >= max natural and level <= min(natural + min(roadbed cap, zone capacity)); never a substitute for the production audit"
                                    ),
                                ),
                            ]))),
                        ),
                        (
                            "firstPointEqualsSupportMax",
                            serde_json::json!(scan.map(|s| {
                                s.first_no_cut_deficit_mm.is_some()
                                    && s.first_no_cut_deficit_mm == s.max_no_cut_deficit_mm
                            })),
                        ),
                        ("roadbedFillCapMm", serde_json::json!(roadbed_fill_cap_mm)),
                        ("zoneFillCapacityMm", serde_json::json!(zone_cap_mm)),
                        (
                            "zoneCapacityExcessMm",
                            serde_json::json!(match (required_fill_mm, zone_cap_mm) {
                                (Some(r), Some(c)) => Some(r - c),
                                _ => None,
                            }),
                        ),
                        ("designLevelMmFromSample", serde_json::json!(sample.design_level_mm)),
                        (
                            "designLevelMmFromSite",
                            serde_json::json!(bound
                                .as_ref()
                                .ok()
                                .and_then(|b| b.site.support_level_mm.map(i64::from))),
                        ),
                        (
                            "naturalMinMaxFromParcel",
                            serde_json::json!([sample.natural_min_mm, sample.natural_max_mm]),
                        ),
                        (
                            "naturalMinMaxScope",
                            serde_json::json!(
                                "production CandidateSample.parcel (full parcel, not the support rectangle)"
                            ),
                        ),
                        ("rawDetail", serde_json::json!(raw_detail)),
                        ("rawSample", serde_json::to_value(sample).unwrap()),
                        ("scanAgreesWithProduction", serde_json::json!(scan_agrees)),
                        ("geometryValid", serde_json::json!(geometry_ok)),
                        ("traceCountComplete", serde_json::json!(counts_match)),
                        (
                            "diagnostic_incomplete",
                            serde_json::json!(!(counts_match
                                && bound.is_ok()
                                && geometry_ok
                                && (sample.outcome == "accepted" || raw_detail.is_some()))),
                        ),
                    ]));
                }
                if detail_iter.next().is_some() {
                    request_raw_detail_ok = false;
                }
                sample_binding_valid &= request_binding_ok;
                geometry_valid &= request_geometry_ok;
                raw_detail_persisted &= request_raw_detail_ok;
                let mut note_counts = serde_json::Map::new();
                for entry in rows
                    .iter()
                    .filter(|row| row["state"] == state && row["requestId"] == request_id)
                {
                    if entry["outcome"] == "accepted" {
                        continue;
                    }
                    let key = entry["note"].as_str().unwrap_or("unknown").to_string();
                    let slot = note_counts.entry(key).or_insert(serde_json::json!(0));
                    *slot = serde_json::json!(slot.as_u64().unwrap() + 1);
                }
                per_request.push(serde_json::json!({
                    "state": state, "requestId": request_id, "requestKind": request_kind,
                    "roadId": bc_id,
                    "attempted": trace.attempted, "accepted": trace.accepted,
                    "rejected": trace.rejected, "rejectedTotal": rejected_total,
                    "budgetStopReason": "per-request budget state after this road",
                    "geometryExhausted": trace.geometry_exhausted,
                    "noteBreakdown": note_counts,
                    "samplesStored": trace.samples.len(),
                    "rejectionDetailsStored": trace.rejection_details.len(),
                    "acceptedIdsStored": trace.accepted_ids.len(),
                    "traceCountComplete": counts_match,
                    "rowsBuilt": request_rows,
                    "bindingValid": request_binding_ok,
                    "geometryValid": request_geometry_ok,
                    "scanAgreesWithProduction": request_scan_ok,
                    "rawDetailPersisted": request_raw_detail_ok,
                }));
            }
            let gains: Vec<usize> = trial
                .realized_totals()
                .iter()
                .zip(&before)
                .map(|((_, after), (_, prior))| after.saturating_sub(*prior))
                .collect();
            if !outcome.check(&clock, budget_ms, "after-measure") {
                stop = true;
                break;
            }
            let _ = gains;
        }
        let (published_best, published_incomplete, expired_at) = outcome.finish(&clock, budget_ms);
        assert!(published_best.is_none() && !published_incomplete);
        let baseline_plan_hash_after = {
            let mut hasher = blake3::Hasher::new();
            hasher.update(&serde_json::to_vec(&plan).unwrap());
            hasher.finalize().to_hex().to_string()
        };
        let reason_totals = {
            let mut map = std::collections::BTreeMap::new();
            for row in &rows {
                if row["outcome"] == "accepted" {
                    continue;
                }
                let key = row["note"].as_str().unwrap_or("unknown").to_string();
                *map.entry(key).or_insert(0_u32) += 1;
            }
            map
        };
        let schema = serde_json::json!({
            "traceCountComplete": trace_count_complete,
            "sampleBindingValid": sample_binding_valid,
            "geometryValid": geometry_valid,
            "rawDetailPersisted": raw_detail_persisted,
            "profilePersisted": profile_persisted,
            "note": "five independent flags; a single detailComplete flag is never used as proof of a complete or correct diagnosis",
        });
        let all_complete = trace_count_complete
            && sample_binding_valid
            && geometry_valid
            && raw_detail_persisted
            && profile_persisted;
        assert!(
            all_complete,
            "the corrected diagnosis must bind every attempt to the real candidate building and persist raw evidence; schema={schema}"
        );
        let payload = json_map(vec![
                ("format", serde_json::json!("glyphweave.b01-g6-r1-diagnostic-repair.run")),
                ("version", serde_json::json!(1)),
                (
                    "replacesEntry",
                    serde_json::json!(
                        "v5_frontage_rejection_diagnosis (B01-G6), whose 32 rows described the BC road instead of the candidate building"
                    ),
                ),
                ("tableHashAlgorithm", serde_json::json!("blake3")),
                ("tableHash", serde_json::json!(table_hash)),
                ("tablePreExisting", serde_json::json!(table_reused)),
                (
                    "frozen",
                    serde_json::json!({
                        "manifest": "bevy/work/collaboration/ds-b04-c1-r2-b02-w1/w1-collector-local.manifest.json",
                        "seed": world_seed, "declaredSource": "AuthoredSeed", "precise": true,
                        "baselineEdges": 35, "baselineNodes": 27, "fixedRootMm": fixed_root_mm,
                    }),
                ),
                ("crossCheckedInferMinimum", serde_json::json!(cross_checked_minimum)),
                ("recordedR1CMm", serde_json::json!(-382)),
                ("sampleCap", serde_json::json!(sample_cap)),
                ("baselinePlanHashBefore", serde_json::json!(baseline_plan_hash)),
                ("baselinePlanHashAfter", serde_json::json!(baseline_plan_hash_after)),
                ("callCounts", counts),
                ("schema", schema),
                (
                    "h1Retraction",
                    serde_json::json!({
                        "retracted": "the B01-G6 claim that lifting the street platform by >=696mm clears the 28 natural_above_design_level rejections",
                        "why": "696mm was only the largest deficit at the first violating point production stops on; each row's supportNoCutMaxDeficitMm is the deficit at the highest natural point of the whole building+2m support rectangle and is larger",
                        "alsoRetracted": "raising B is not equivalent to lifting every BC pad: road_alignment::solve is a per-point lower-bound slope envelope, so a higher B only lifts the part it actually dominates",
                        "workedExampleNoNewRun": "at B=3000 with junctionLengthM=9 the station-42 design is 1105mm; a B of 3696 would propagate only 3696-80*(42-9)=1056mm of lower bound to that station, which is below the existing 1105mm, so no +696 lift can be inferred there",
                        "status": "no new B/C value was evaluated; H1 is not approved and is not executed in this round",
                    }),
                ),
                ("seconds", serde_json::json!(started.elapsed().as_secs_f64())),
                ("incomplete", serde_json::json!(published_incomplete || !all_complete)),
                ("expiredAt", serde_json::json!(expired_at)),
                ("attemptRows", serde_json::json!(rows.len())),
                ("reasonTotals", serde_json::json!(reason_totals)),
                ("perRequest", serde_json::json!(per_request)),
                ("profiles", serde_json::json!(profiles)),
                ("rawTraces", serde_json::json!(raw_traces)),
                ("rows", serde_json::json!(rows)),
        ]);
        assert_no_tagged_result(&payload, "$");
        println!(
            "{}",
            serde_json::to_string_pretty(&payload).unwrap()
        );
    }

    /// Test-only: the accepted measurement path extends the plan with the sites
    /// the session already committed; the diagnostic replay has no committed
    /// sites, so this returns the same empty list the G5 run used.
    fn session_occupied_placeholder() -> Vec<super::super::road_network::RoadsideSite> {
        vec![]
    }

    /// Test-only: hash a serializable evidence payload the way the run binds its
    /// profiles.
    fn hash_json<T: serde::Serialize>(value: &T) -> String {
        let mut hasher = blake3::Hasher::new();
        hasher.update(&serde_json::to_vec(value).unwrap());
        hasher.finalize().to_hex().to_string()
    }

    /// Test-only: build a JSON object from a flat entry list. `serde_json::json!`
    /// reaches its recursion limit on the wide evidence rows, so the row shape is
    /// assembled explicitly instead of by one huge macro literal.
    fn json_map(entries: Vec<(&str, serde_json::Value)>) -> serde_json::Value {
        serde_json::Value::Object(
            entries
                .into_iter()
                .map(|(key, value)| (key.to_string(), value))
                .collect(),
        )
    }

    /// Test-only: published evidence must never carry a tagged `Result` shape.
    /// A `Result::map` where an `Option::map` was meant serializes as
    /// `{"Ok": ...}` (or `{"Err": ...}`), which is how the first corrected run
    /// shipped seven geometry fields in the wrong shape.
    fn assert_no_tagged_result(value: &serde_json::Value, path: &str) {
        match value {
            serde_json::Value::Object(map) => {
                if map.len() == 1 {
                    if let Some(key) = map.keys().next() {
                        assert!(
                            key != "Ok" && key != "Err",
                            "published evidence carries a tagged Result at {path}: {value}"
                        );
                    }
                }
                for (key, child) in map {
                    assert_no_tagged_result(child, &format!("{path}.{key}"));
                }
            }
            serde_json::Value::Array(items) => {
                for (index, child) in items.iter().enumerate() {
                    assert_no_tagged_result(child, &format!("{path}[{index}]"));
                }
            }
            _ => {}
        }
    }

