    /// Test-only: full-signature equality of two carves. The "every component
    /// other than the connection is unchanged" comparison uses this, so a moved
    /// centre, a re-blended ring, a re-prioritised pad or a single profile sample
    /// moved by 1mm is a mismatch instead of a silently accepted neighbour.
    fn g1b_same_carve(a: &super::super::TerrainCarve, b: &super::super::TerrainCarve) -> bool {
        let close = |x: f64, y: f64| (x - y).abs() <= 1e-9;
        a.priority == b.priority
            && a.disturbance == b.disturbance
            && close(a.cx, b.cx)
            && close(a.cz, b.cz)
            && close(a.half_w, b.half_w)
            && close(a.half_d, b.half_d)
            && close(a.blend_m, b.blend_m)
            && close(a.target_h_m, b.target_h_m)
            && profile_contents_match(a.profile.as_deref(), b.profile.as_deref())
    }

    /// Test-only: signature of a diagnostic baseline (carves plus their explicit
    /// owner tags), so "both candidates start from the same candidate-free
    /// baseline" is re-checked instead of asserted from construction order.
    fn g1b_baseline_signature(
        carves: &[super::super::TerrainCarve],
        tags: &[CarveTag],
    ) -> serde_json::Value {
        serde_json::Value::Array(
            carves
                .iter()
                .zip(tags.iter())
                .map(|(carve, tag)| {
                    json_map(vec![
                        ("owner", serde_json::json!(tag.owner_entity_id)),
                        ("component", serde_json::json!(tag.component)),
                        ("cx", serde_json::json!(carve.cx)),
                        ("cz", serde_json::json!(carve.cz)),
                        ("halfW", serde_json::json!(carve.half_w)),
                        ("halfD", serde_json::json!(carve.half_d)),
                        ("priority", serde_json::json!(carve.priority)),
                        ("targetMm", serde_json::json!(height_mm(carve.target_h_m))),
                        ("blendM", serde_json::json!(carve.blend_m)),
                        (
                            "profileHash",
                            match carve.profile.as_deref() {
                                Some(profile) => serde_json::json!(hash_json(profile)),
                                None => serde_json::Value::Null,
                            },
                        ),
                    ])
                })
                .collect(),
        )
    }

    /// Test-only: locate one candidate's connection carve. A tag/carve length
    /// mismatch, a missing owner and a duplicated connection tag are all explicit
    /// errors; the first match is never silently taken.
    fn g1b_connection_index(
        carves: &[super::super::TerrainCarve],
        tags: &[CarveTag],
        site_id: &str,
    ) -> Result<usize, String> {
        if carves.len() != tags.len() {
            return Err(format!(
                "carve/tag length mismatch for {site_id}: {} carves, {} tags",
                carves.len(),
                tags.len()
            ));
        }
        let mut found: Option<usize> = None;
        for (index, tag) in tags.iter().enumerate() {
            if tag.owner_entity_id == site_id && tag.component == "connection" {
                if let Some(first) = found {
                    return Err(format!(
                        "ambiguous connection carve for {site_id}: indices {first} and {index}"
                    ));
                }
                found = Some(index);
            }
        }
        found.ok_or_else(|| format!("no connection carve for {site_id}"))
    }

    /// Test-only: every component other than `changed` must keep its complete
    /// signature and the changed one must really differ. Returns how many
    /// components were compared, so the caller can prove the range was not empty.
    fn g1b_only_index_changed(
        before: &[super::super::TerrainCarve],
        after: &[super::super::TerrainCarve],
        changed: usize,
    ) -> Result<usize, String> {
        if before.len() != after.len() {
            return Err(format!(
                "carve list length changed: {} -> {}",
                before.len(),
                after.len()
            ));
        }
        if changed >= before.len() {
            return Err(format!(
                "changed index {changed} is outside a list of {}",
                before.len()
            ));
        }
        let mut compared = 0_usize;
        for index in 0..before.len() {
            if index == changed {
                continue;
            }
            if !g1b_same_carve(&before[index], &after[index]) {
                return Err(format!(
                    "non-connection component {index} changed, but only index {changed} may"
                ));
            }
            compared += 1;
        }
        if g1b_same_carve(&before[changed], &after[changed]) {
            return Err(format!(
                "the connection component {changed} did not change at all"
            ));
        }
        Ok(compared)
    }

    /// Test-only: replace ONLY the candidate's connection carve, keeping pad and
    /// apron untouched. The supplied tags are first checked against the verified
    /// production identity, then the connection is located by uniqueness; a
    /// missing owner, a duplicated connection, a length mismatch, a swapped
    /// tag/carve pairing or any collateral change to another component is a
    /// refusal with a reason, never a silent first pick.
    fn g1b_replace_connection(
        entities: &[EntityInstance],
        carves: &[super::super::TerrainCarve],
        tags: &[CarveTag],
        site_id: &str,
        anchor_z: f64,
    ) -> Result<(Vec<super::super::TerrainCarve>, usize), String> {
        let verified = verify_carve_identity(entities, carves)?;
        if verified.len() != tags.len() {
            return Err(format!(
                "supplied tag/carve length mismatch for {site_id}: {} verified identities, {} tags",
                verified.len(),
                tags.len()
            ));
        }
        for (index, (want, got)) in verified.iter().zip(tags.iter()).enumerate() {
            if want.owner_entity_id != got.owner_entity_id
                || want.owner_kind != got.owner_kind
                || want.component != got.component
            {
                return Err(format!(
                    "tag/carve identity mismatch at index {index}: supplied {}/{} but the verified identity is {}/{}",
                    got.owner_entity_id, got.component, want.owner_entity_id, want.component
                ));
            }
        }
        let index = g1b_connection_index(carves, &verified, site_id)?;
        let old = &carves[index];
        let mut replaced = carves.to_vec();
        replaced[index] = g1b_connection(old.cx, anchor_z, old.target_h_m);
        let compared = g1b_only_index_changed(carves, &replaced, index)?;
        debug_assert_eq!(compared, carves.len() - 1);
        Ok((replaced, index))
    }

    /// Test-only: the clamp rule of the production frontage sample
    /// (`terrain_height_zoned`: protected -> natural; engineered <= natural ->
    /// natural; otherwise the zone fill cap) with an injected natural surface,
    /// so a synthetic probe can report the raw carve composition and the
    /// frontage-口径 clamped value side by side. The rule is copied from that
    /// function; the natural floor flag, the protected flag and the cap are
    /// returned separately instead of being folded into one number.
    fn g1b_frontage_clamped(
        natural_m: f64,
        x: i32,
        z: i32,
        carves: &[super::super::TerrainCarve],
        mask: &super::super::zoning::ZoningMask,
    ) -> (f64, bool, f64, bool) {
        let protected = mask.protected_at(x, z);
        let cap_m = mask.fill_capacity_at(x, z);
        let engineered = super::super::apply_terrain_carves(natural_m, x, z, carves);
        if carves.is_empty() || protected || engineered <= natural_m {
            return (natural_m, protected, cap_m, true);
        }
        (engineered.min(natural_m + cap_m), protected, cap_m, false)
    }

    /// Test-only: the sampling guard. A cell outside the declared scene, a
    /// non-finite natural surface, a non-finite carve target or blend, and a
    /// tag/carve length mismatch are refused with a reason, so a missing sample
    /// can never be reported as a number.
    fn g1b_sample_input_check(
        scene: &super::super::SceneSpec,
        natural_m: f64,
        x: i32,
        z: i32,
        carves: &[super::super::TerrainCarve],
        tags: &[CarveTag],
    ) -> Result<(), String> {
        if carves.len() != tags.len() {
            return Err(format!(
                "carve/tag length mismatch: {} carves, {} tags",
                carves.len(),
                tags.len()
            ));
        }
        let inside_x = i64::from(x) >= i64::from(scene.origin_x)
            && i64::from(x) < i64::from(scene.origin_x) + i64::from(scene.width_m);
        let inside_z = i64::from(z) >= i64::from(scene.origin_z)
            && i64::from(z) < i64::from(scene.origin_z) + i64::from(scene.depth_m);
        if !inside_x || !inside_z {
            return Err(format!(
                "sample ({x},{z}) is outside the declared scene origin ({}, {}) size {}x{}",
                scene.origin_x, scene.origin_z, scene.width_m, scene.depth_m
            ));
        }
        if !natural_m.is_finite() {
            return Err(format!("illegal natural sample at ({x},{z}): {natural_m}"));
        }
        for (index, carve) in carves.iter().enumerate() {
            if !carve.target_h_m.is_finite() {
                return Err(format!(
                    "illegal carve target at index {index} ({}/{}): {}",
                    tags[index].owner_entity_id, tags[index].component, carve.target_h_m
                ));
            }
            if !carve.blend_m.is_finite() || carve.blend_m < 0.0 {
                return Err(format!(
                    "illegal carve blend at index {index} ({}/{}): {}",
                    tags[index].owner_entity_id, tags[index].component, carve.blend_m
                ));
            }
        }
        Ok(())
    }

    /// Test-only: read an integer millimetre field or refuse loudly. No evidence
    /// field may fall back to a fabricated zero.
    fn g1b_mm(value: &serde_json::Value, key: &str) -> i64 {
        value
            .get(key)
            .and_then(serde_json::Value::as_i64)
            .unwrap_or_else(|| {
                panic!("evidence field {key} is missing or is not integer millimetres: {value}")
            })
    }

    /// Test-only: read a string evidence field or refuse loudly.
    fn g1b_text(value: &serde_json::Value, key: &str) -> String {
        value
            .get(key)
            .and_then(serde_json::Value::as_str)
            .unwrap_or_else(|| panic!("evidence field {key} is missing or is not a string: {value}"))
            .to_string()
    }

    /// Test-only: read a boolean evidence field or refuse loudly.
    fn g1b_flag(value: &serde_json::Value, key: &str) -> bool {
        value
            .get(key)
            .and_then(serde_json::Value::as_bool)
            .unwrap_or_else(|| {
                panic!("evidence field {key} is missing or is not a boolean: {value}")
            })
    }

    /// Test-only: replicate production `apply_terrain_carves` step by step and
    /// report which carve actually decided the cell.
    ///
    /// A priority tie is not a source: inside the top priority group the branch
    /// value is the *maximum* target, so a lower target that merely ties on
    /// priority is reported as a cover that did not decide. Ring entries are
    /// split into potential fillers, fillers that really raised the running
    /// value, and ring fill that the final full-target override erased. When the
    /// override does not apply at all (`graded_influence` false or no full
    /// cover) the maximum-based composition decides and the branch value is
    /// reported but marked inactive.
    ///
    /// The blend lists hold ring fill only: a fully covering pad that raises the
    /// running value is recorded in `coverAppliedDuringLoop` instead. Lowering by
    /// the override is reported as `overrideLoweredValue`; calling it a blend
    /// erasure additionally requires a named ring source whose applied fill lies
    /// above the final value, so `blendErasedSources` is never empty when
    /// `blendErasedByOverride` is true.
    fn g1b_decide(
        natural_m: f64,
        x: i32,
        z: i32,
        carves: &[super::super::TerrainCarve],
        tags: &[CarveTag],
    ) -> serde_json::Value {
        let entry = |index: usize, outside: f64, target: f64| {
            json_map(vec![
                ("index", serde_json::json!(index)),
                ("owner", serde_json::json!(tags[index].owner_entity_id)),
                ("component", serde_json::json!(tags[index].component)),
                ("priority", serde_json::json!(carves[index].priority)),
                ("outsideM", serde_json::json!(outside)),
                ("blendM", serde_json::json!(carves[index].blend_m)),
                ("targetMm", serde_json::json!((target * 1000.).round() as i64)),
            ])
        };
        let base = natural_m.clamp(-32.0, 256.0);
        let mut terrain = base;
        let mut graded_influence = false;
        let mut full_priority = i32::MIN;
        let mut full_target = base;
        let mut covers: Vec<usize> = vec![];
        let mut blend_potential: Vec<usize> = vec![];
        let mut blend_applied: Vec<(usize, f64)> = vec![];
        let mut cover_applied: Vec<usize> = vec![];
        for (index, carve) in carves.iter().enumerate() {
            let (_, _, outside, target, limit, full_cover) = carve_relation(carve, natural_m, x, z);
            if carve.profile.is_some() && outside < carve.blend_m {
                graded_influence = true;
            }
            if full_cover {
                covers.push(index);
                if carve.priority >= full_priority {
                    if carve.priority > full_priority {
                        full_target = base;
                    }
                    full_priority = carve.priority;
                    full_target = full_target.max(target);
                }
            }
            let before = terrain;
            if full_cover {
                terrain = terrain.max(target.min(limit));
                if terrain > before + 1e-9 {
                    cover_applied.push(index);
                }
            } else if outside < carve.blend_m && target > base {
                let t = (outside / carve.blend_m).clamp(0.0, 1.0);
                let smooth_t = t * t * (3.0 - 2.0 * t);
                let fill = target + (base - target) * smooth_t;
                blend_potential.push(index);
                let applied = fill.min(limit);
                terrain = terrain.max(applied);
                if terrain > before + 1e-9 {
                    blend_applied.push((index, applied));
                }
            }
        }
        let terrain_after_loop = terrain;
        let branch_active = graded_influence && full_priority != i32::MIN;
        if branch_active {
            terrain = full_target;
        }
        let value = terrain.clamp(-32.0, 256.0);
        let relations = |indices: &[usize]| -> Vec<serde_json::Value> {
            indices
                .iter()
                .map(|&index| {
                    let (_, _, outside, target, _, _) =
                        carve_relation(&carves[index], natural_m, x, z);
                    entry(index, outside, target)
                })
                .collect()
        };
        let at_top_priority = |lower: bool| -> Vec<serde_json::Value> {
            let chosen: Vec<usize> = covers
                .iter()
                .copied()
                .filter(|&index| {
                    let (_, _, _, target, _, _) = carve_relation(&carves[index], natural_m, x, z);
                    carves[index].priority == full_priority
                        && if lower {
                            target < full_target - 1e-9
                        } else {
                            (target - full_target).abs() <= 1e-9
                        }
                })
                .collect();
            relations(&chosen)
        };
        let naturally_decided = branch_active && (full_target - base).abs() <= 1e-9;
        let override_lowered = branch_active && terrain_after_loop > value + 1e-9;
        // A ring source is erased only when the override is active and that ring
        // fill really sat above the final value; this is the source evidence the
        // claim needs, and it can never be satisfied by a full-cover pad.
        let blend_erased: Vec<(usize, f64)> = blend_applied
            .iter()
            .copied()
            .filter(|(_, applied)| branch_active && *applied > value + 1e-9)
            .collect();
        let blend_erased_by_override = !blend_erased.is_empty();
        let value_source = if branch_active {
            if naturally_decided {
                "full_branch_kept_natural"
            } else {
                "full_target_branch"
            }
        } else if terrain_after_loop > base + 1e-9 {
            "terrain_max_without_full_branch"
        } else {
            "natural_lower_bound"
        };
        json_map(vec![
            (
                "baseTerrainMm",
                serde_json::json!((base * 1000.).round() as i64),
            ),
            ("gradedInfluence", serde_json::json!(graded_influence)),
            (
                "fullTargetBranchActive",
                serde_json::json!(branch_active),
            ),
            (
                "fullTopPriority",
                if full_priority == i32::MIN {
                    serde_json::Value::Null
                } else {
                    serde_json::json!(full_priority)
                },
            ),
            (
                "fullTargetMm",
                serde_json::json!((full_target * 1000.).round() as i64),
            ),
            (
                "terrainAfterLoopMm",
                serde_json::json!((terrain_after_loop * 1000.).round() as i64),
            ),
            ("valueMm", serde_json::json!((value * 1000.).round() as i64)),
            ("valueSource", serde_json::json!(value_source)),
            ("fullCovers", serde_json::json!(relations(&covers))),
            (
                "fullTargetSources",
                serde_json::json!(at_top_priority(false)),
            ),
            (
                "fullTargetLowerTiedAtTopPriority",
                serde_json::json!(at_top_priority(true)),
            ),
            (
                "blendPotential",
                serde_json::json!(relations(&blend_potential)),
            ),
            (
                "blendAppliedDuringLoop",
                serde_json::json!(relations(
                    &blend_applied
                        .iter()
                        .map(|(index, _)| *index)
                        .collect::<Vec<_>>()
                )),
            ),
            (
                "coverAppliedDuringLoop",
                serde_json::json!(relations(&cover_applied)),
            ),
            (
                "overrideLoweredValue",
                serde_json::json!(override_lowered),
            ),
            (
                "blendErasedSources",
                serde_json::json!(relations(
                    &blend_erased
                        .iter()
                        .map(|(index, _)| *index)
                        .collect::<Vec<_>>()
                )),
            ),
            (
                "blendErasedByOverride",
                serde_json::json!(blend_erased_by_override),
            ),
        ])
    }

    /// Test-only: the diagnostic publish path. The payload is computed first and
    /// the deadline is re-checked before anything may be written, so a clock that
    /// expires between the computation and the output publishes nothing.
    fn g1b_publish(
        clock: &dyn SupplyClock,
        budget_ms: u64,
        payload: serde_json::Value,
    ) -> (Option<serde_json::Value>, bool, Option<&'static str>) {
        let mut outcome = BundleOutcome::new();
        if !outcome.stage_witness(clock, budget_ms, payload) {
            return (None, true, outcome.expired_at);
        }
        outcome.finish(clock, budget_ms)
    }

    /// Test-only: one point probe. A sample that does not exist is refused first;
    /// the raw carve composition, the decision provenance and the frontage-口径
    /// clamped sample are then reported side by side. The replicated decision
    /// must reproduce the production value exactly, so a divergent winner model
    /// fails the test instead of silently mislabelling a source.
    fn g1b_probe(
        scene: &super::super::SceneSpec,
        natural_m: f64,
        x: i32,
        z: i32,
        carves: &[super::super::TerrainCarve],
        tags: &[CarveTag],
        mask: &super::super::zoning::ZoningMask,
    ) -> Result<serde_json::Value, String> {
        g1b_sample_input_check(scene, natural_m, x, z, carves, tags)?;
        let decision = g1b_decide(natural_m, x, z, carves, tags);
        let value = super::super::apply_terrain_carves(natural_m, x, z, carves);
        assert_eq!(
            g1b_mm(&decision, "valueMm"),
            height_mm(value),
            "the replicated decision and apply_terrain_carves disagree at ({x},{z})"
        );
        let (clamped, protected, cap_m, natural_floor) =
            g1b_frontage_clamped(natural_m, x, z, carves, mask);
        Ok(json_map(vec![
            ("cell", serde_json::json!([x, z])),
            ("naturalMm", serde_json::json!(height_mm(natural_m))),
            ("valueMm", serde_json::json!(height_mm(value))),
            (
                "frontageClampedMm",
                serde_json::json!(height_mm(clamped)),
            ),
            ("protectedAt", serde_json::json!(protected)),
            (
                "zoneFillCapMm",
                if cap_m.is_finite() {
                    serde_json::json!(height_mm(cap_m))
                } else {
                    serde_json::Value::Null
                },
            ),
            ("zoneFillCapInfinite", serde_json::json!(!cap_m.is_finite())),
            ("naturalFloorActive", serde_json::json!(natural_floor)),
            ("decision", decision),
        ]))
    }

